-- Prague activities
INSERT INTO activities (id, slug, destination_id, name, description, price, min_price, duration, image_url, includes,
                        seo_indexable, translations, created_at)
VALUES ('9f692d2c-e165-4c3c-a578-488f611421b1', 'ak-47-glock-17-shooting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'AK-47 and Glock 17 Shooting',
        'Fire two of the world''s most iconic firearms in one session: the legendary AK-47 and the Glock 17, the pistol trusted by police forces around the world. This 90-minute guided experience in Prague is built for complete beginners — a qualified instructor stays with your group the whole time, covering safe handling before you send your first round downrange. The package includes 15 rounds of 7.62×39 for the AK-47 and 10 rounds for the Glock 17, with all equipment and safety gear provided. Shooting is a natural fit for a stag do: it''s a genuine skill test, and it takes seconds to turn the session into a competition — crown the group''s top shot and let the loser buy the first round back in town. Book it as a daytime activity and the whole evening stays free.',
        55.00, NULL, 90,
        'https://img.trivlu.com/ba3c0544-bb2f-4649-9025-47e0865bf133.jpg',
        'Qualified Instructor; 15 bullets AK-47; Equipment & Safety Gear; 10 bullets Glock 17',
        TRUE, '{"de":{"name":"Schießen mit AK-47 und Glock 17","includes":"Qualifizierter Instruktor; 15 Schuss AK-47; Ausrüstung & Schutzausrüstung; 10 Schuss Glock 17","description":"Feuere in einer Session zwei der bekanntesten Schusswaffen der Welt ab: die legendäre AK-47 und die Glock 17, die Pistole, der Polizeikräfte weltweit vertrauen. Dieses 90-minütige geführte Erlebnis in Prag ist für komplette Anfänger gemacht — ein qualifizierter Instruktor bleibt die ganze Zeit bei deiner Gruppe und erklärt den sicheren Umgang, bevor der erste Schuss fällt. Das Paket enthält 15 Schuss 7,62×39 für die AK-47 und 10 Schuss für die Glock 17, Ausrüstung und Schutzausrüstung inklusive. Schießen passt perfekt zum JGA: Es ist ein echter Skill-Test, und in Sekunden wird aus der Session ein Wettbewerb — küre den besten Schützen der Gruppe und lass den Verlierer in der Stadt die erste Runde zahlen. Buche es als Tagesaktivität und der ganze Abend bleibt frei."}}', CURRENT_TIMESTAMP),
       ('2bf7dd65-b061-43cf-adf1-58e3e2cdbddd', 'army-tank-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Army Tank Experience',
        'Not many stag do activities let you climb aboard genuine Soviet-era armour. On this one your group heads out of Prague with private roundtrip transport to a site where a real BMP-1 infantry fighting vehicle is waiting. You get a 20-minute ride across proper rugged terrain — mud, hills and engine roar included — with expert guidance the whole way, so no experience is needed. The visit also includes a walk around the military museum, where you can get up close to more hardware from another era, plus a soft drink to round things off. It is a loud, heavy, grin-inducing hour that works brilliantly as a daytime centrepiece: pure adrenaline for the petrolheads in the group, great photos for everyone else, and a story the stag will retell for years.',
        55.00, NULL, 60,
        'https://img.trivlu.com/7444f6b8-0ddb-4d0e-9021-0652effc529e.webp',
        'Private Transport (Roundtrip); 20 min. BMP-1 Ride; Soft drink each; Visit of military museum',
        TRUE, '{"de":{"name":"Panzer-Erlebnis","includes":"Privater Transport (Hin- und Rückfahrt); 20 Min. BMP-1-Fahrt; Softdrink pro Person; Besuch des Militärmuseums","description":"Nicht viele JGA-Aktivitäten lassen dich auf echte Panzertechnik aus Sowjetzeiten klettern. Bei dieser fährt deine Gruppe mit privatem Hin- und Rücktransport aus Prag raus zu einem Gelände, auf dem ein echter BMP-1 Schützenpanzer wartet. Du bekommst eine 20-minütige Fahrt durch richtig raues Gelände — Schlamm, Hügel und Motorengebrüll inklusive — mit fachkundiger Begleitung die ganze Zeit, Erfahrung ist also nicht nötig. Zum Besuch gehört auch ein Rundgang durch das Militärmuseum, wo du noch mehr Technik aus einer anderen Ära aus nächster Nähe siehst, plus ein Softdrink zum Abschluss. Eine laute, schwere Stunde, die jeden zum Grinsen bringt und als Tages-Highlight brillant funktioniert: pures Adrenalin für die Benzinköpfe in der Gruppe, großartige Fotos für alle anderen und eine Geschichte, die der Bräutigam noch Jahre erzählen wird."}}', CURRENT_TIMESTAMP),
       ('09cfbcf1-1846-4201-ae40-eaf3ef999db2', 'axe-throwing', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Axe Throwing',
        'Channel your inner warrior on a three-hour throwing session that goes well beyond axes. Under the eye of a qualified instructor, your group works through a full hour of axe throwing, an hour of knife throwing and an hour of shuriken throwing across two dedicated targets, starting with a proper safety briefing so complete beginners can join in. Private roundtrip transport gets everyone there and back without any planning, and there is a cold Czech beer or soft drink for each of you along the way. It is a brilliant stag do format: easy to learn, weirdly addictive, and naturally competitive — keep score across all three weapons and crown an overall champion. Book it for the afternoon and you will arrive at dinner with sharper aim and better stories.',
        33.00, NULL, 180,
        'https://img.trivlu.com/07b184b8-27e7-463e-8053-fee0c7153896.jpg',
        'Private Transport (Roundtrip); 2 Targets; hour of Axe Throwing; hour of Knives throwing; hour of Shuriken throwing; 5 min. Safety briefing; Qualified Instructor; 1 Beer or Softdrink Each',
        TRUE, '{"de":{"name":"Axtwerfen","includes":"Privater Transport (Hin- und Rückfahrt); 2 Zielscheiben; Eine Stunde Axtwerfen; Eine Stunde Messerwerfen; Eine Stunde Shuriken-Werfen; 5 Min. Sicherheitseinweisung; Qualifizierter Instruktor; 1 Bier oder Softdrink pro Person","description":"Weck den Krieger in dir bei einer dreistündigen Wurf-Session, die weit über Äxte hinausgeht. Unter den Augen eines qualifizierten Instruktors arbeitet sich deine Gruppe durch eine volle Stunde Axtwerfen, eine Stunde Messerwerfen und eine Stunde Shuriken-Werfen an zwei eigenen Zielscheiben — mit einer ordentlichen Sicherheitseinweisung zu Beginn, damit auch komplette Anfänger mitmachen können. Privater Hin- und Rücktransport bringt alle ohne Planungsaufwand hin und zurück, und unterwegs gibt es für jeden ein kaltes tschechisches Bier oder einen Softdrink. Ein brillantes JGA-Format: leicht zu lernen, seltsam süchtig machend und von Natur aus kompetitiv — führe über alle drei Waffen Punkte und küre einen Gesamtsieger. Buche es für den Nachmittag und du kommst mit schärferem Auge und besseren Geschichten zum Abendessen."}}', CURRENT_TIMESTAMP),
       ('34cf39ef-b8ff-4457-881f-cef7bd85beaf', 'beer-olympics', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Beer Olympics',
        'Split the group into teams, pour the first round and let the games begin. Beer Olympics in Prague is a two-hour private tournament built around giant beer pong, classic beer pong, blow football and a basket-connect challenge, with an instructor running the show so the rules stay roughly fair. Beer, soft drinks and water are unlimited for the full two hours, and private roundtrip transport is included, so nobody has to think about logistics. It is one of the easiest wins on a stag do: every skill level can compete, the rivalry builds round by round, and there is a podium moment at the end for the bragging-rights photo. Ideal as an afternoon warm-up before Prague''s nightlife — competitive enough to matter, silly enough that losing is half the fun.',
        109.00, NULL, 120,
        'https://img.trivlu.com/8da7c84a-677c-4628-a10c-5dd0a8ae8243.jpg',
        'Private Transport (Roundtrip); 2 hrs. Unlimited beer soft drinks & water; Qualified Instructor; Giant beer pong game; Beer pong game; Blow football game; Basket connect game',
        TRUE, '{"de":{"name":"Bier-Olympiade","includes":"Privater Transport (Hin- und Rückfahrt); 2 Std. unbegrenzt Bier, Softdrinks & Wasser; Qualifizierter Instruktor; Riesen-Bierpong; Bierpong; Blasfußball; Basket-Connect-Spiel","description":"Teile die Gruppe in Teams, schenk die erste Runde ein und lass die Spiele beginnen. Die Bier-Olympiade in Prag ist ein zweistündiges privates Turnier rund um Riesen-Bierpong, klassisches Bierpong, Blasfußball und eine Basket-Connect-Challenge, mit einem Instruktor, der das Ganze leitet, damit die Regeln halbwegs fair bleiben. Bier, Softdrinks und Wasser sind die vollen zwei Stunden unbegrenzt, privater Hin- und Rücktransport ist inklusive — niemand muss an Logistik denken. Einer der leichtesten Siege auf einem JGA: Jedes Niveau kann mitspielen, die Rivalität wächst Runde für Runde, und am Ende gibt es einen Podiumsmoment für das Angeber-Foto. Ideal als Warm-up am Nachmittag vor Prags Nachtleben — kompetitiv genug, um zu zählen, albern genug, dass Verlieren der halbe Spaß ist."}}', CURRENT_TIMESTAMP),
       ('7f7dc51e-b96d-47bb-bbd7-460f2d43b33e', 'beer-spa', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Beer Spa',
        'Only in the Czech Republic: a spa session where the tub is filled with beer. Your group gets a 30-minute private beer bath, followed by a full hour in the relaxation zone to let the whole experience sink in. Unlimited Czech beer flows for 90 minutes, with salty snacks to keep you going, and towels, sheets and slippers are all provided — just turn up. A Trivlu guide accompanies the group so everything runs smoothly from start to finish. It is the perfect mid-weekend reset on a Prague stag do: warm water, hops and a cold glass in hand repair morale after a big night, and the novelty factor makes it one of the most photographed stops of the trip. Block out around three hours and come out feeling human again.',
        113.00, NULL, 180,
        'https://img.trivlu.com/ba9ba7d2-61e2-42f2-a9a5-73336d833341.jpg',
        'Trivlu Guide; 30 min. Private Beer Spa; 60 min. Relaxation zone; 90 min. Unlimited beer; Salty snacks; Towels and sheets; Slippers each',
        TRUE, '{"de":{"name":"Bier-Spa","includes":"Trivlu-Guide; 30 Min. privates Bier-Spa; 60 Min. Relax-Zone; 90 Min. unbegrenzt Bier; Salzige Snacks; Handtücher und Laken; Pantoffeln pro Person","description":"Nur in Tschechien: eine Spa-Session, bei der die Wanne mit Bier gefüllt ist. Deine Gruppe bekommt ein 30-minütiges privates Bierbad, gefolgt von einer vollen Stunde in der Relax-Zone, um das Erlebnis sacken zu lassen. 90 Minuten lang fließt unbegrenzt tschechisches Bier, salzige Snacks halten dich bei Laune, und Handtücher, Laken und Pantoffeln werden gestellt — einfach hinkommen. Ein Trivlu-Guide begleitet die Gruppe, damit von Anfang bis Ende alles rund läuft. Der perfekte Reset mitten im Prager JGA-Wochenende: warmes Wasser, Hopfen und ein kaltes Glas in der Hand reparieren die Moral nach einer langen Nacht, und der Neuheitsfaktor macht es zu einem der meistfotografierten Stopps der Reise. Plane rund drei Stunden ein und komm wieder menschlich raus."}}', CURRENT_TIMESTAMP),
       ('faeebc99-9c0b-4ef8-bb6d-6bb9bd380abb', 'beer-tasting-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Beer Tasting Experience',
        'Czech beer is the national religion, and this two-hour tasting is the friendly introduction service. With a reserved table waiting and a Trivlu guide leading the session, your group samples five different 0.2-litre draft pours, learning what separates the traditional brewery styles and local favourites along the way. Once you have found your winner, each of you gets two full 0.5-litre glasses of your favourite to settle in with. It is a relaxed, social format that suits every kind of group — no beer knowledge required, just curiosity and thirst. As a stag do activity it works beautifully in the early evening: you drink well, you learn enough to sound clever in every pub afterwards, and you walk out with a shortlist of beers to order for the rest of the weekend.',
        30.00, NULL, 120,
        'https://img.trivlu.com/4fa58b74-08cc-46ff-b3b7-51e7e2f75a4b.jpg',
        'Trivlu Guide; 5 glasses 0.2L draft beer for degustation; Table reservation; 2 glasses 0.5L of favourite beer each',
        TRUE, '{"de":{"name":"Bierverkostung","includes":"Trivlu-Guide; 5 Gläser 0,2 l Fassbier zur Verkostung; Tischreservierung; 2 Gläser 0,5 l Lieblingsbier pro Person","description":"Tschechisches Bier ist die Nationalreligion, und diese zweistündige Verkostung ist die freundliche Einführung. Mit reserviertem Tisch und einem Trivlu-Guide, der die Session leitet, probiert deine Gruppe fünf verschiedene 0,2-Liter-Fassbiere und lernt nebenbei, was die traditionellen Brauereistile und lokalen Favoriten unterscheidet. Hast du deinen Sieger gefunden, bekommt jeder zwei volle 0,5-Liter-Gläser seines Lieblingsbiers zum Einrichten. Ein entspanntes, geselliges Format, das zu jeder Gruppe passt — kein Bierwissen nötig, nur Neugier und Durst. Als JGA-Aktivität funktioniert es wunderbar am frühen Abend: Du trinkst gut, lernst genug, um danach in jeder Kneipe klug zu klingen, und gehst mit einer Shortlist an Bieren für den Rest des Wochenendes raus."}}', CURRENT_TIMESTAMP),
       ('7c93d80c-f175-45bf-b980-beb62b24d89a', 'bowling-and-beers', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Bowling and Beers',
        'Some stag do afternoons need structure, and a bowling lane provides exactly that. This two-hour session in a modern city-centre venue includes private lane hire for the group, all the equipment you need, and three beers each to keep the frames flowing. A Trivlu guide gets you there and settled so you can go straight into the first game. Ten-pin bowling is the great leveller — everyone has played, nobody is actually good, and a scoreboard turns any group of mates into fierce rivals within minutes. Set up a simple forfeit for last place and the room takes care of itself. It is an easy, weatherproof option that slots in perfectly between a heavy lunch and a big night, and it leaves everyone warmed up rather than worn out.',
        27.00, NULL, 120,
        'https://img.trivlu.com/45f2c4a2-b865-42a9-a20d-c4633ed42343.jpg',
        'Trivlu Guide; Equipment & Safety Gear; 2 hrs. Bowling Lane Hire; 3 Beer each',
        TRUE, '{"de":{"name":"Bowling und Bier","includes":"Trivlu-Guide; Ausrüstung & Schutzausrüstung; 2 Std. Bowlingbahn; 3 Bier pro Person","description":"Manche JGA-Nachmittage brauchen Struktur, und eine Bowlingbahn liefert genau das. Diese zweistündige Session in einer modernen Location im Stadtzentrum umfasst eine private Bahn für die Gruppe, die komplette Ausrüstung und drei Biere pro Person, damit die Frames in Fluss bleiben. Ein Trivlu-Guide bringt dich hin und sorgt dafür, dass du direkt ins erste Spiel starten kannst. Bowling ist der große Gleichmacher — jeder hat es schon gespielt, keiner ist wirklich gut, und eine Anzeigetafel macht aus jeder Gruppe von Kumpels in Minuten erbitterte Rivalen. Leg eine einfache Strafe für den letzten Platz fest und der Rest läuft von allein. Eine einfache, wetterfeste Option, die perfekt zwischen ein schweres Mittagessen und eine große Nacht passt und alle aufgewärmt statt erledigt zurücklässt."}}', CURRENT_TIMESTAMP),
       ('443547b7-41fb-467c-9e5a-b7f3df8293f2', 'breakfast-with-tiffany', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Breakfast With Tiffany',
        'The most famous hangover cure on the Trivlu menu, with a twist the name only hints at. Breakfast With Tiffany books your group a proper full English — two sausages, two eggs, two strips of bacon, two hash browns, black and white pudding, tomato, mushrooms, beans and toast, with orange juice each — and pairs the fry-up with a 15-minute private show performance to make sure everyone is fully awake. A Trivlu guide arranges the whole sitting. It is the classic Prague stag do morning: the food repairs the damage from last night, the entertainment restarts the group''s sense of humour, and the whole hour sets exactly the right tone for the day ahead. Come for the bacon, stay for the story.',
        40.00, 120.00, 60,
        'https://img.trivlu.com/adf122ba-fbc2-40c2-8980-d5e0414f4d85.jpg',
        'Trivlu Guide; 2 Sausage each; 2 Eggs each; 2 Strip of bacon each; 2 Hashbrown each; Black and white pudding each; Tomato each; Mushrooms each; Beans each; Toast each; Orange Juice (0.2 l) each; 15 min. Strip Show',
        TRUE, '{"de":{"name":"Frühstück mit Tiffany","includes":"Trivlu-Guide; 2 Würstchen pro Person; 2 Eier pro Person; 2 Streifen Bacon pro Person; 2 Hash Browns pro Person; Black und White Pudding pro Person; Tomate pro Person; Pilze pro Person; Bohnen pro Person; Toast pro Person; Orangensaft (0,2 l) pro Person; 15 Min. Stripshow","description":"Das berühmteste Katerfrühstück auf der Trivlu-Karte, mit einem Twist, den der Name nur andeutet. Frühstück mit Tiffany bucht deiner Gruppe ein richtiges Full English — zwei Würstchen, zwei Eier, zwei Streifen Bacon, zwei Hash Browns, Black und White Pudding, Tomate, Pilze, Bohnen und Toast, dazu Orangensaft für jeden — und kombiniert das Frühstück mit einer 15-minütigen privaten Show, damit garantiert alle wach sind. Ein Trivlu-Guide organisiert den gesamten Termin. Der klassische Prager JGA-Morgen: Das Essen repariert die Schäden der letzten Nacht, die Unterhaltung startet den Humor der Gruppe neu, und die ganze Stunde setzt genau den richtigen Ton für den Tag. Komm wegen des Bacons, bleib wegen der Geschichte."}}', CURRENT_TIMESTAMP),
       ('c521b179-4872-4dec-8bd7-42cd92f68e45', 'bubble-football', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Bubble Football',
        'Take football, remove all dignity, add giant inflatable zorbs. Bubble football in Prague puts your group inside huge bubbles for an hour of playing time, then lets you bounce, barge and roll your way through a match that nobody manages to take seriously. A qualified instructor and a referee keep the chaos organised, all equipment and safety gear is provided, and there is a beer for each player when the whistle finally goes. A Trivlu guide handles the meet-up so the group just turns up and plays. It is one of the most reliably funny stag do activities there is: fitness helps less than you would think, big hits are painless, and the video footage is guaranteed gold. Perfect as a daytime energy burner before the evening plans begin.',
        37.00, NULL, 60,
        'https://img.trivlu.com/24a0aeb0-b3d5-43b2-848a-0f70bb68f4a1.jpg',
        'Trivlu Guide; Qualified Instructor; hr. Playing Time; Equipment & Safety Gear; Beer(s) each; Referee',
        TRUE, '{"de":{"name":"Bubble-Fußball","includes":"Trivlu-Guide; Qualifizierter Instruktor; 1 Std. Spielzeit; Ausrüstung & Schutzausrüstung; Bier pro Person; Schiedsrichter","description":"Nimm Fußball, entferne jede Würde, füg riesige aufblasbare Zorbs hinzu. Bubble Football in Prag steckt deine Gruppe für eine Stunde Spielzeit in riesige Blasen und lässt sie dann durch ein Match hüpfen, rempeln und rollen, das niemand ernst nehmen kann. Ein qualifizierter Instruktor und ein Schiedsrichter halten das Chaos organisiert, Ausrüstung und Schutzausrüstung werden gestellt, und wenn endlich abgepfiffen wird, gibt es für jeden Spieler ein Bier. Ein Trivlu-Guide kümmert sich um den Treffpunkt, die Gruppe kommt einfach und spielt. Eine der verlässlich lustigsten JGA-Aktivitäten überhaupt: Fitness hilft weniger, als man denkt, große Zusammenstöße tun nicht weh, und das Videomaterial ist garantiertes Gold. Perfekt als Energie-Verbrenner am Tag, bevor die Abendpläne beginnen."}}', CURRENT_TIMESTAMP),
       ('4643201e-7ab7-4f06-b55a-8b892f773aca', 'burger-and-private-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Burger & Private Show',
        'Dinner and a show, stag do edition. This 100-minute experience seats your group in a private restaurant setting in central Prague for a proper cheeseburger with fries, sauce and two beers each — solid fuel for the evening ahead. Once the plates are cleared, the room turns into a venue: a private 15-minute show performance for your group, with a spotlight moment reserved for one selected guest (no prizes for guessing who). A Trivlu guide books everything and keeps the evening on schedule. It is an efficient, crowd-pleasing combination — everyone eats well, nobody has to move between venues, and the entertainment lands in front of exactly the audience it was booked for. An easy early-evening anchor before Prague''s nightlife takes over.',
        40.00, NULL, 100,
        'https://img.trivlu.com/417d31e3-412d-42a9-8a08-6c4828ac2b84.jpg',
        'Trivlu Guide; Burger each; French fries each; Sauce each; 2 Beer per person; 15 minutes Strip Show',
        TRUE, '{"de":{"name":"Burger & Private Show","includes":"Trivlu-Guide; Burger pro Person; Pommes pro Person; Sauce pro Person; 2 Bier pro Person; 15 Minuten Stripshow","description":"Dinner und Show, JGA-Edition. Dieses 100-minütige Erlebnis setzt deine Gruppe in einem privaten Restaurantbereich im Zentrum Prags an den Tisch — für einen richtigen Cheeseburger mit Pommes, Sauce und zwei Bier pro Person — solide Grundlage für den Abend. Sind die Teller abgeräumt, wird der Raum zur Bühne: eine private 15-minütige Show für deine Gruppe, mit einem Spotlight-Moment für einen ausgewählten Gast (kein Preis fürs Raten, wer). Ein Trivlu-Guide bucht alles und hält den Abend im Zeitplan. Eine effiziente Kombination, die allen gefällt — alle essen gut, niemand muss die Location wechseln, und die Unterhaltung landet genau bei dem Publikum, für das sie gebucht wurde. Ein leichter Anker für den frühen Abend, bevor Prags Nachtleben übernimmt."}}', CURRENT_TIMESTAMP),
       ('f71bc594-85f8-4990-a4e9-caab68cc7aea', 'car-demolition-in-prague', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Car Demolition in Prague',
        'Every group has someone who just wants to smash something. Car Demolition in Prague hands them a real car and full permission. In a controlled, supervised setting with a qualified instructor, your group takes turns destroying an actual vehicle, with all equipment and safety gear provided so the only thing at risk is the car itself. Private roundtrip transport is included, along with water to cool down between rounds, and a Trivlu guide keeps the day running smoothly. It is a pure, cathartic hour of noise and broken glass — the kind of thing you will never get to do at home, which is precisely what a Prague stag do is for. Bring the group''s frustrations, leave them in the wreckage, and arrive at dinner with spectacular photos.',
        151.00, 500.00, 60,
        'https://img.trivlu.com/27fbd072-bba7-4823-ad38-d1aece1065d2.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); Car Demolition; Qualified Instructor; Equipment & Safety Gear; Water each',
        TRUE, '{"de":{"name":"Auto-Zertrümmern in Prag","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Auto zertrümmern; Qualifizierter Instruktor; Ausrüstung & Schutzausrüstung; Wasser pro Person","description":"In jeder Gruppe gibt es jemanden, der einfach etwas kaputtmachen will. Auto zertrümmern in Prag gibt ihm ein echtes Auto und die volle Erlaubnis. In einem kontrollierten, beaufsichtigten Rahmen mit qualifiziertem Instruktor zerlegt deine Gruppe abwechselnd ein echtes Fahrzeug, Ausrüstung und Schutzausrüstung inklusive — das Einzige, was hier zu Schaden kommt, ist das Auto. Privater Hin- und Rücktransport ist inklusive, dazu Wasser zum Abkühlen zwischen den Runden, und ein Trivlu-Guide hält den Tag am Laufen. Eine pure, befreiende Stunde aus Lärm und Glasbruch — das, was man zu Hause nie darf, und genau dafür ist ein JGA in Prag da. Bring den Frust der Gruppe mit, lass ihn im Wrack und komm mit spektakulären Fotos zum Abendessen."}}', CURRENT_TIMESTAMP),
       ('34b6da09-4a27-423c-b22c-42c6c8b6719f', 'car-football', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Car football',
        'Football logic, motoring chaos. Car football puts your group behind the wheel for a full hour of bumper-to-bumper sport, using cars to shove an oversized ball towards goal in a game that rewards teamwork, nerve and a total disregard for tidy driving. Private transfer to the venue is included, a Trivlu guide keeps the day organised, and there is a beer for each player once the final whistle goes. No motorsport experience is needed — control matters more than speed, and the funniest moments usually come from the least qualified drivers. As a stag do activity it hits a rare sweet spot: genuinely novel, fiercely competitive and absurd enough that the retelling gets better every time. Plan around two and a half hours door to door and bring a camera.',
        160.00, NULL, 140,
        'https://img.trivlu.com/90981e6d-012e-4a96-aab4-f41d5c7c57a6.jpg',
        'Trivlu guide; Private transfer; 1 hour of car football; beer each',
        TRUE, '{"de":{"name":"Autofußball","includes":"Trivlu-Guide; Privater Transfer; 1 Stunde Autofußball; Bier pro Person","description":"Fußball-Logik, Auto-Chaos. Autofußball setzt deine Gruppe für eine volle Stunde Stoßstange-an-Stoßstange-Sport ans Steuer: Mit Autos schiebst du einen überdimensionalen Ball Richtung Tor — ein Spiel, das Teamwork, Nerven und völlige Missachtung ordentlicher Fahrweise belohnt. Privater Transfer zur Location ist inklusive, ein Trivlu-Guide hält den Tag organisiert, und nach dem Schlusspfiff gibt es ein Bier für jeden Spieler. Motorsport-Erfahrung ist nicht nötig — Kontrolle zählt mehr als Tempo, und die lustigsten Momente liefern meist die am wenigsten qualifizierten Fahrer. Als JGA-Aktivität trifft es einen seltenen Sweet Spot: wirklich neu, erbittert kompetitiv und absurd genug, dass die Nacherzählung jedes Mal besser wird. Plane rund zweieinhalb Stunden von Tür zu Tür ein und bring eine Kamera mit."}}', CURRENT_TIMESTAMP),
       ('78e1691a-7225-4fe5-b7d2-adbebcca9133', 'card-games-evening', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Card Games Evening',
        'A private, casino-style night without the casino crowds. Card Games Evening books your group a private underground venue for a full six hours, with dedicated tables set up for poker, blackjack and other classics, and a 1,000 CZK bar voucher for each of you to keep the drinks moving. A Trivlu guide gets everyone settled, then the night is entirely yours: set the buy-ins, run a tournament bracket, or just deal hands until the small hours. Because the room is reserved exclusively for your group, the atmosphere is exactly what you make it — high-stakes and silent or loud and ridiculous. It is a brilliant stag do option for groups who want a proper night together rather than a queue for a bar, and the winner buys breakfast.',
        74.00, NULL, 360,
        'https://img.trivlu.com/c9089530-cbb7-431b-aedf-a91f447cca94.webp',
        'Trivlu Guide; 6 hrs. Private room hire; 1 000 CZK bar voucher each; Tables for card games',
        TRUE, '{"de":{"name":"Kartenspiel-Abend","includes":"Trivlu-Guide; 6 Std. private Raummiete; Bar-Gutschein 1.000 CZK pro Person; Tische für Kartenspiele","description":"Eine private Nacht im Casino-Stil ohne Casino-Publikum. Der Kartenspiel-Abend bucht deiner Gruppe sechs volle Stunden eine private Underground-Location mit eigenen Tischen für Poker, Blackjack und andere Klassiker, plus einen Bar-Gutschein über 1.000 CZK für jeden, damit die Drinks fließen. Ein Trivlu-Guide bringt alle unter, dann gehört die Nacht ganz dir: Leg die Buy-ins fest, spiel ein Turnier durch oder gib einfach bis in die frühen Morgenstunden Karten. Da der Raum exklusiv für deine Gruppe reserviert ist, ist die Atmosphäre genau das, was du daraus machst — High Stakes und still oder laut und albern. Eine brillante JGA-Option für Gruppen, die einen richtigen gemeinsamen Abend wollen statt einer Schlange vor der Bar — und der Gewinner zahlt das Frühstück."}}', CURRENT_TIMESTAMP),
       ('791aecfd-9054-4115-b1f5-cead7003e89d', 'casino-night', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Casino Night',
        'Put the group''s luck to the test on a proper Prague casino night. With casino entry arranged, your evening runs through poker, blackjack, roulette and slots in a lively setting in the heart of the city. A Trivlu guide comes armed with local tips, and free entry to selected Prague clubs is included, so when the chips run out the night simply moves on rather than winding down. It is a classic stag do format for good reason: the tables give the evening a focus, fortunes swing fast enough to keep everyone invested, and there is always one member of the group who walks out insufferably up. Dress the part, set a sensible budget each, and let the cards decide who is buying the first round at the club afterwards.',
        26.00, NULL, 180,
        'https://img.trivlu.com/198dd86b-0ed5-47c2-a17b-2591a9883e35.jpg',
        'Trivlu Guide; Local tips; Free entry to chosen clubs in Prague; Casino entry',
        TRUE, '{"de":{"name":"Casino-Nacht","includes":"Trivlu-Guide; Lokale Tipps; Freier Eintritt in ausgewählte Clubs in Prag; Casino-Eintritt","description":"Stell das Glück der Gruppe bei einer echten Prager Casino-Nacht auf die Probe. Mit organisiertem Casino-Eintritt läuft dein Abend durch Poker, Blackjack, Roulette und Slots in lebendiger Atmosphäre im Herzen der Stadt. Ein Trivlu-Guide kommt mit Insider-Tipps, und freier Eintritt in ausgewählte Prager Clubs ist inklusive — gehen die Chips aus, zieht die Nacht einfach weiter, statt auszuklingen. Ein JGA-Klassiker aus gutem Grund: Die Tische geben dem Abend einen Fokus, das Glück wendet sich schnell genug, um alle bei der Stange zu halten, und irgendjemand aus der Gruppe geht immer unerträglich im Plus raus. Zieh dich passend an, leg pro Kopf ein vernünftiges Budget fest und lass die Karten entscheiden, wer danach im Club die erste Runde zahlt."}}', CURRENT_TIMESTAMP),
       ('feee540e-8b67-4cf7-bf18-163f44487c44', 'clay-pigeon-shooting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Clay Pigeon Shooting',
        'Fast targets, loaded shotguns and a leaderboard — clay pigeon shooting was practically invented for stag groups. Just outside Prague, with private roundtrip transport included, your group takes on 12 clay pigeons each with 24 cartridges to bring them down, all under the supervision of a qualified instructor and with full equipment and safety gear provided. Beers and soft drinks are included for when the shooting is done, and a Trivlu guide manages the whole outing. Beginners are genuinely welcome: the instructor covers stance and technique before anyone calls pull, and hitting your first moving target is a feeling that does not fade. Score it properly, crown the best gun, and give the worst shot a forfeit for the evening. Allow around two and a half hours all in.',
        106.00, NULL, 150,
        'https://img.trivlu.com/71988218-6ae2-4062-9199-1571690fc85b.webp',
        'Trivlu Guide; Private Transport (Roundtrip); Soft Drinks; Qualified Instructor; Equipment & Safety Gear; 12 Clay Pigeons each; Beer(s) each; 24 bullets each',
        TRUE, '{"de":{"name":"Tontaubenschießen","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Softdrinks; Qualifizierter Instruktor; Ausrüstung & Schutzausrüstung; 12 Tontauben pro Person; Bier pro Person; 24 Patronen pro Person","description":"Schnelle Ziele, geladene Flinten und eine Rangliste — Tontaubenschießen wurde praktisch für JGA-Gruppen erfunden. Direkt vor Prag, privater Hin- und Rücktransport inklusive, nimmt sich deine Gruppe 12 Tontauben pro Person vor, mit 24 Patronen, um sie vom Himmel zu holen — alles unter Aufsicht eines qualifizierten Instruktors und mit kompletter Ausrüstung und Schutzausrüstung. Bier und Softdrinks für die Zeit nach dem Schießen sind inklusive, und ein Trivlu-Guide managt den gesamten Ausflug. Anfänger sind wirklich willkommen: Der Instruktor erklärt Stand und Technik, bevor jemand „Pull“ ruft, und das erste bewegliche Ziel zu treffen ist ein Gefühl, das nicht verblasst. Führe richtig Punkte, küre den besten Schützen und verpass dem schlechtesten eine Strafe für den Abend. Plane insgesamt rund zweieinhalb Stunden ein."}}', CURRENT_TIMESTAMP),
       ('00642d11-dfea-4092-88a3-ea65ff33dd94', 'cocktails-karaoke-night', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Cocktails & Karaoke night',
        'Some nights need a microphone. This two-hour session reserves your group a table at a Prague karaoke spot, with a cocktail for each of you to loosen the vocal cords, and a Trivlu guide to get everyone there and settled. After that, the playlist is yours: duets, power ballads, questionable rap covers and the inevitable moment the stag is forced through a solo. Karaoke is a stag do secret weapon — it needs no skill, gets funnier as the night goes on, and turns even the quietest member of the group into a headline act. It slots in perfectly as an early-evening warm-up before the clubs or as the main event for groups who would rather sing badly together than queue anywhere. Book it, pick your anthem, commit.',
        35.00, NULL, 120,
        'https://img.trivlu.com/d09b4df1-9b1f-4333-b9c3-5b9309ff05a0.webp',
        'Trivlu Guide; Table in Karaoke; Cocktail each',
        TRUE, '{"de":{"name":"Cocktails & Karaoke-Nacht","includes":"Trivlu-Guide; Tisch in der Karaoke-Bar; Cocktail pro Person","description":"Manche Nächte brauchen ein Mikrofon. Diese zweistündige Session reserviert deiner Gruppe einen Tisch in einer Prager Karaoke-Bar, mit einem Cocktail für jeden, um die Stimmbänder zu lockern, und einem Trivlu-Guide, der alle hinbringt und unterbringt. Danach gehört die Playlist dir: Duette, Powerballaden, fragwürdige Rap-Cover und der unvermeidliche Moment, in dem der Bräutigam zum Solo gezwungen wird. Karaoke ist eine JGA-Geheimwaffe — braucht kein Talent, wird mit jeder Stunde lustiger und macht selbst den Stillsten der Gruppe zum Headliner. Passt perfekt als Warm-up am frühen Abend vor den Clubs oder als Hauptprogramm für Gruppen, die lieber gemeinsam schlecht singen, als irgendwo anzustehen. Buchen, Hymne wählen, durchziehen."}}', CURRENT_TIMESTAMP),
       ('643bd314-91ee-442d-95be-a64c305791b4', 'czech-dinner-with-national-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Czech dinner with national show',
        'Eat like a local, loudly. This 90-minute dinner books your group a reserved table for a three-course traditional Czech menu, served alongside three beers and a national shot per person, while a live national-style show with music and entertainment plays out around you. A Trivlu guide gets the group seated and the evening rolling. It is the easiest way to tick off authentic Czech culture on a stag weekend without sacrificing the party atmosphere: hearty food that soaks up a long day, drinks that keep the table lively, and a performance that gives the evening a proper sense of occasion. Ideal as the anchor meal of the trip — everyone eats well, everyone drinks well, and the group rolls out ready for whatever Prague''s nightlife has planned next.',
        78.00, NULL, 90,
        'https://img.trivlu.com/eb5aedfd-04d7-42ff-b5c3-96ed4e80cffd.png',
        'Trivlu Guide; Table reservation; 3 beers and 1 national shot per person; 3 course czech traditional menu',
        TRUE, '{"de":{"name":"Tschechisches Dinner mit Folklore-Show","includes":"Trivlu-Guide; Tischreservierung; 3 Bier und 1 nationaler Schnaps pro Person; Traditionelles tschechisches 3-Gänge-Menü","description":"Iss wie die Einheimischen — und zwar laut. Dieses 90-minütige Dinner bucht deiner Gruppe einen reservierten Tisch für ein traditionelles tschechisches Drei-Gänge-Menü, dazu drei Biere und einen nationalen Schnaps pro Person, während rund um deinen Tisch eine Live-Folklore-Show mit Musik und Unterhaltung läuft. Ein Trivlu-Guide bringt die Gruppe an den Tisch und den Abend ins Rollen. Der einfachste Weg, auf einem JGA-Wochenende authentische tschechische Kultur abzuhaken, ohne die Partystimmung zu opfern: deftiges Essen, das einen langen Tag aufsaugt, Drinks, die den Tisch lebendig halten, und eine Show, die dem Abend einen richtigen Rahmen gibt. Ideal als Anker-Mahlzeit der Reise — alle essen gut, alle trinken gut, und die Gruppe rollt bereit für alles raus, was Prags Nachtleben als Nächstes geplant hat."}}', CURRENT_TIMESTAMP),
       ('cdaaf49a-e073-4532-b0f6-fef3a8e36381', 'czech-lunch-or-dinner', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Czech Lunch or Dinner',
        'Traditional Czech cooking with a distinctly untraditional finale. Your group gets a reserved sitting with a national Czech dish and two beers each — proper hearty local food that refuels a stag weekend the way the locals would approve of. Then, as the plates go, the surprise arrives: a 15-minute show performance rounds off the meal and turns dinner into the evening''s first story. A Trivlu guide arranges the table and the timing so the reveal lands right. It is a neat two-in-one for groups that want authentic Czech cuisine without a quiet, forgettable dinner — 90 minutes that start as culture and end as entertainment, sending the group out the door laughing and ready for the rest of the night.',
        40.00, NULL, 90,
        'https://img.trivlu.com/9db4e597-b265-4c93-ad25-db92ab7dc628.jpeg',
        'Trivlu Guide; National Czech dish each; 2 Beer each; 15 minutes Strip Show',
        TRUE, '{"de":{"name":"Tschechisches Mittag- oder Abendessen","includes":"Trivlu-Guide; Tschechisches Nationalgericht pro Person; 2 Bier pro Person; 15 Minuten Stripshow","description":"Traditionelle tschechische Küche mit einem ausgesprochen untraditionellen Finale. Deine Gruppe bekommt einen reservierten Tisch mit einem tschechischen Nationalgericht und zwei Bier pro Person — richtig deftiges lokales Essen, das ein JGA-Wochenende so auftankt, wie die Einheimischen es gutheißen würden. Und wenn die Teller gehen, kommt die Überraschung: Eine 15-minütige Show rundet die Mahlzeit ab und macht das Abendessen zur ersten Geschichte des Abends. Ein Trivlu-Guide organisiert Tisch und Timing, damit die Enthüllung genau sitzt. Ein schönes Zwei-in-eins für Gruppen, die authentische tschechische Küche ohne ein ruhiges, vergessliches Dinner wollen — 90 Minuten, die als Kultur beginnen und als Unterhaltung enden und die Gruppe lachend und bereit für den Rest der Nacht zur Tür rausschicken."}}', CURRENT_TIMESTAMP),
       ('418febeb-117e-436f-80dc-4f25764ed76d', 'dog-chase', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Dog chase',
        'The premise is beautifully simple: the dog is fast, and your stag thinks he is faster. Dog Chase is one of the stranger prank experiences on the Prague list — an hour-long outing where the groom discovers exactly how he performs with a trained dog on his heels while the rest of the group enjoys the show from a very safe distance. A Trivlu guide runs the whole thing and public transport to the venue is covered, so all you need to bring is a stag with working legs and a group ready to film every second. It is short, ridiculous and completely unforgettable — the kind of story that defines a stag weekend. Ask us for the full details when booking; some surprises are better left unspoiled for the groom.',
        35.00, 430.00, 60,
        'https://img.trivlu.com/836b5964-7c03-4efc-88b8-6c7182b88548.jpg',
        'Trivlu Guide; Public Transport; Dog chase',
        TRUE, '{"de":{"name":"Hundejagd","includes":"Trivlu-Guide; Öffentliche Verkehrsmittel; Hundejagd","description":"Die Prämisse ist wunderbar einfach: Der Hund ist schnell, und dein Bräutigam hält sich für schneller. Die Hundejagd ist eines der schrägeren Prank-Erlebnisse auf der Prag-Liste — ein einstündiger Ausflug, bei dem der Bräutigam herausfindet, wie er sich mit einem trainierten Hund an den Fersen schlägt, während der Rest der Gruppe die Show aus sehr sicherer Entfernung genießt. Ein Trivlu-Guide leitet das Ganze, die öffentlichen Verkehrsmittel zur Location sind abgedeckt — du brauchst nur einen Bräutigam mit funktionierenden Beinen und eine Gruppe, die jede Sekunde filmt. Kurz, absurd und völlig unvergesslich — die Art Geschichte, die ein JGA-Wochenende definiert. Frag uns bei der Buchung nach allen Details; manche Überraschungen sollte man dem Bräutigam lieber nicht verraten."}}', CURRENT_TIMESTAMP),
       ('4f0a7149-8174-4d52-8387-8c257e809dd1', 'dungeon-of-horror-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Dungeon Of Horror Experience',
        'Lock the group in a haunted cellar and see who screams first. Dungeon of Horror is a 25-minute horror escape experience beneath Prague, where your team solves puzzles to find a way out of eerie rooms and catacombs while the atmosphere does its best to break your nerve. The session opens with a safety briefing, a qualified instructor oversees the experience, and the package includes a haunted house tour, two drinks each and photos and videos of your finest panicked moments. A Trivlu guide handles the logistics. It is short, sharp and hilarious in hindsight — ideal between daytime activities and dinner, and a guaranteed way to find out which member of the group is secretly the biggest coward. The footage afterwards settles it beyond argument.',
        29.00, NULL, 41,
        'https://img.trivlu.com/9e43e219-dd83-46b4-b612-c0a7ca0d4a6b.jpg',
        'Trivlu Guide; Qualified Instructor; Haunted house tour; 2 Drink(s) each; Safety briefing; Photos and videos',
        TRUE, '{"de":{"name":"Dungeon of Horror","includes":"Trivlu-Guide; Qualifizierter Instruktor; Geisterhaus-Tour; 2 Drinks pro Person; Sicherheitseinweisung; Fotos und Videos","description":"Sperr die Gruppe in einen Spukkeller und schau, wer zuerst schreit. Dungeon of Horror ist ein 25-minütiges Horror-Escape-Erlebnis unter Prag, bei dem dein Team Rätsel löst, um aus unheimlichen Räumen und Katakomben herauszufinden, während die Atmosphäre alles tut, um deine Nerven zu brechen. Die Session beginnt mit einer Sicherheitseinweisung, ein qualifizierter Instruktor überwacht das Erlebnis, und das Paket enthält eine Geisterhaus-Tour, zwei Drinks pro Person sowie Fotos und Videos deiner schönsten Panikmomente. Ein Trivlu-Guide kümmert sich um die Logistik. Kurz, knackig und im Nachhinein urkomisch — ideal zwischen Tagesaktivitäten und Abendessen und ein garantierter Weg herauszufinden, wer in der Gruppe heimlich der größte Angsthase ist. Das Filmmaterial danach klärt es endgültig."}}', CURRENT_TIMESTAMP),
       ('0a31e118-cba7-4473-8e81-de9d7ea2e3f1', 'dwarf-hire', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Dwarf Hire',
        'Some stag do bookings need no lengthy explanation, and Dwarf Hire is one of them. For a full hour, a professional entertainer joins your Prague night out and turns an ordinary bar stop into the chapter of the weekend everyone retells first. How the hour unfolds is largely up to your group — as a surprise for the stag, a partner in crime for the evening, or simply the most memorable plus-one in Prague. It is a booking for groups who want their night to have a twist that no amount of bar-hopping can provide, and it pairs naturally with the city''s nightlife stops. Short, absurd and guaranteed to dominate the group chat the next morning — which, on a stag weekend, is the whole point.',
        31.00, 280.00, 90,
        'https://img.trivlu.com/8dd87f5b-6c74-45b7-8335-2f8117a89cce.jpg',
        'Hour of Midget Entertainer',
        TRUE, '{"de":{"name":"Kleinwüchsiger Entertainer","includes":"Eine Stunde kleinwüchsiger Entertainer","description":"Manche JGA-Buchungen brauchen keine lange Erklärung, und diese ist eine davon. Für eine volle Stunde begleitet ein professioneller Entertainer deine Nacht in Prag und macht aus einem gewöhnlichen Bar-Stopp das Kapitel des Wochenendes, das alle zuerst erzählen. Wie die Stunde verläuft, liegt größtenteils an deiner Gruppe — als Überraschung für den Bräutigam, als Komplize für den Abend oder einfach als denkwürdigste Begleitung in Prag. Eine Buchung für Gruppen, die ihrer Nacht einen Twist geben wollen, den kein Bar-Hopping liefern kann, und die sich natürlich mit den Nachtleben-Stopps der Stadt kombinieren lässt. Kurz, absurd und garantiert das Thema im Gruppenchat am nächsten Morgen — was auf einem JGA-Wochenende der ganze Sinn ist."}}', CURRENT_TIMESTAMP),
       ('dee1feb4-7238-438b-a3dd-b2f58ab584c9', 'extreme-archery', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Extreme Archery',
        'Paintball without the mess, Robin Hood with a scoreboard. Extreme Archery arms your group with Olympic-style bows for a full hour of playing time in a cool indoor arena in central Prague — a former film location used by Hollywood productions including Angelina Jolie''s ''Wanted'', which gives the whole showdown a properly cinematic backdrop. All equipment and safety gear is provided, there is a costume for the stag, and each player gets a beer or soft drink. A Trivlu guide keeps the session running. The format is instantly addictive: dodge, draw, loose, and argue about whether that hit counted. It suits every fitness level, leaves no bruises worth complaining about, and produces the kind of team rivalry that carries through the rest of the weekend. Book the arena, bring your aim.',
        42.00, NULL, 90,
        'https://img.trivlu.com/4299b02a-45db-470b-ba49-a81403067170.jpg',
        'Trivlu Guide; Equipment & Safety Gear; Costume for stag; Beer(s) or Soft Drink(s) each; Hour of Playing Time',
        TRUE, '{"de":{"name":"Bogensport Extrem","includes":"Trivlu-Guide; Ausrüstung & Schutzausrüstung; Kostüm für den Bräutigam; Bier oder Softdrink pro Person; Eine Stunde Spielzeit","description":"Paintball ohne die Sauerei, Robin Hood mit Anzeigetafel. Extreme Archery rüstet deine Gruppe mit Bögen im Olympia-Stil für eine volle Stunde Spielzeit in einer coolen Indoor-Arena im Zentrum Prags aus — einer ehemaligen Filmlocation, die von Hollywood-Produktionen wie Angelina Jolies „Wanted“ genutzt wurde und dem Showdown eine richtig cineastische Kulisse gibt. Ausrüstung und Schutzausrüstung werden gestellt, es gibt ein Kostüm für den Bräutigam, und jeder Spieler bekommt ein Bier oder einen Softdrink. Ein Trivlu-Guide hält die Session am Laufen. Das Format macht sofort süchtig: ausweichen, spannen, schießen und streiten, ob der Treffer gezählt hat. Es passt zu jedem Fitnesslevel, hinterlässt keine nennenswerten blauen Flecken und erzeugt die Art Team-Rivalität, die den Rest des Wochenendes trägt. Buche die Arena, bring deine Zielsicherheit mit."}}', CURRENT_TIMESTAMP),
       ('c7877c90-bce3-4000-9204-034f20cffc93', 'foot-darts', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Foot Darts',
        'Darts, except the dartboard is enormous and you kick footballs at it. Foot Darts gives your group a full hour of playing time on a giant board, with a qualified instructor keeping score, equipment provided and private roundtrip transport included. There is a beer or water for each player, a Trivlu guide manages the outing, and optional prank scenarios can be arranged if the stag deserves special treatment. The beauty of the format is that football skill only half-translates — accuracy under pressure is a different game, and the group''s five-a-side hero missing the board entirely never stops being funny. Play it as singles, doubles or a full tournament with forfeits. An easy, sociable afternoon activity that leaves everyone laughing rather than limping.',
        49.00, NULL, 150,
        'https://img.trivlu.com/268e1c19-5591-4e6b-bdf8-1f749deb4389.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); Qualified Instructor; 60 min. Playing Time; beer or water each; Equipment & Safety Gear',
        TRUE, '{"de":{"name":"Fußball-Darts","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Qualifizierter Instruktor; 60 Min. Spielzeit; Bier oder Wasser pro Person; Ausrüstung & Schutzausrüstung","description":"Darts, nur dass die Dartscheibe riesig ist und du Fußbälle darauf schießt. Fußball-Darts gibt deiner Gruppe eine volle Stunde Spielzeit an einer Riesenscheibe, mit einem qualifizierten Instruktor, der die Punkte zählt, gestellter Ausrüstung und privatem Hin- und Rücktransport. Es gibt ein Bier oder Wasser für jeden Spieler, ein Trivlu-Guide managt den Ausflug, und auf Wunsch lassen sich Prank-Szenarien arrangieren, falls der Bräutigam eine Sonderbehandlung verdient. Das Schöne am Format: Fußballtalent überträgt sich nur zur Hälfte — Präzision unter Druck ist ein anderes Spiel, und es hört nie auf, lustig zu sein, wenn der Hallenfußball-Held der Gruppe die Scheibe komplett verfehlt. Spiel Einzel, Doppel oder ein ganzes Turnier mit Strafen. Eine leichte, gesellige Nachmittagsaktivität, nach der alle lachen statt humpeln."}}', CURRENT_TIMESTAMP),
       ('b97a1b9c-7fbe-4438-9503-f98742fa9135', 'footgolf', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Footgolf',
        'Golf''s calm, football''s chaos — footgolf splits the difference perfectly. Your group plays a 90-minute round on a proper course just outside Prague, kicking footballs towards oversized holes and discovering that a delicate chip is much harder with your feet. Private roundtrip transport is included and a Trivlu guide keeps the day on schedule, so the whole outing runs itself. The course is open from April to October, making this a great-weather pick for a daytime stag do slot. No golf etiquette, no equipment to master, no handicap required — just an easy, social sport where trash talk is mandatory and every hole produces at least one spectacular miss. Score it properly, play for a forfeit, and settle once and for all who in the group actually has a left foot.',
        39.00, NULL, 120,
        'https://img.trivlu.com/1d841abd-59b9-4f3b-9334-a7ff1e5c8b02.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); 90 min. FotbalGolf game',
        TRUE, '{"de":{"name":"Fußballgolf","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); 90 Min. Footgolf-Runde","description":"Die Ruhe des Golfs, das Chaos des Fußballs — Footgolf trifft perfekt die Mitte. Deine Gruppe spielt eine 90-minütige Runde auf einem richtigen Platz direkt vor Prag, schießt Fußbälle in überdimensionale Löcher und stellt fest, dass ein feiner Chip mit den Füßen deutlich schwerer ist. Privater Hin- und Rücktransport ist inklusive und ein Trivlu-Guide hält den Tag im Zeitplan, der ganze Ausflug läuft also von selbst. Der Platz ist von April bis Oktober geöffnet — eine tolle Schönwetter-Wahl für den Tagesslot eines JGA. Keine Golf-Etikette, keine Ausrüstung zu meistern, kein Handicap nötig — nur ein leichter, geselliger Sport, bei dem Sprüche Pflicht sind und jedes Loch mindestens einen spektakulären Fehlschuss produziert. Zähl richtig, spiel um eine Strafe und klär ein für alle Mal, wer in der Gruppe wirklich einen linken Fuß hat."}}', CURRENT_TIMESTAMP),
       ('588639dd-bfca-472b-af76-2b740f810e59', 'ford-boyard-challenge', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Ford Boyard Challenge',
        'Ninety minutes of play, one mission, and a team that has to earn it. Inspired by the classic adventure format, the Ford Boyard Challenge puts your group through a series of physical and mental trials — puzzles to crack, challenges to survive, and moments where someone has to volunteer for the unpleasant bit. A Trivlu guide runs the day, the stag gets his own T-shirt for the occasion, and there is a beer or soft drink for everyone once the mission is complete. It is a brilliant format for stag groups because it forces actual teamwork: the loudest member of the group is suddenly useless at riddles, the quiet one turns out to be the hero, and the debrief afterwards writes itself. Expect roughly two hours all in.',
        58.00, NULL, 116,
        'https://img.trivlu.com/7a6162be-3dd2-40a7-9549-441c7ab9582d.png',
        'Trivlu Guide; 90 minutes of play; Beer or Softdrink each; T-shirt for Stag',
        TRUE, '{"de":{"name":"Fort-Boyard-Herausforderung","includes":"Trivlu-Guide; 90 Minuten Spiel; Bier oder Softdrink pro Person; T-Shirt für den Bräutigam","description":"Neunzig Minuten Spiel, eine Mission und ein Team, das sie sich verdienen muss. Inspiriert vom klassischen Abenteuerformat schickt die Fort-Boyard-Challenge deine Gruppe durch eine Reihe körperlicher und geistiger Prüfungen — Rätsel zum Knacken, Challenges zum Überstehen und Momente, in denen sich jemand für den unangenehmen Teil freiwillig melden muss. Ein Trivlu-Guide leitet den Tag, der Bräutigam bekommt sein eigenes T-Shirt für den Anlass, und nach erfüllter Mission gibt es ein Bier oder einen Softdrink für alle. Ein brillantes Format für JGA-Gruppen, weil es echtes Teamwork erzwingt: Der Lauteste der Gruppe ist plötzlich nutzlos bei Rätseln, der Stille entpuppt sich als Held, und die Nachbesprechung schreibt sich von selbst. Rechne mit rund zwei Stunden insgesamt."}}', CURRENT_TIMESTAMP),
       ('ac5515c3-98c6-4859-a895-ec10cda21b39', 'full-irish-breakfast', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Full Irish Breakfast',
        'Start the day the way a stag weekend demands: with a table reserved and a proper full Irish waiting. Each of you gets two sausages, two eggs, two strips of bacon and two hash browns, plus black and white pudding, tomato, mushrooms, beans and toast — and two beers, juice or soft drinks each to wash it down, because this is Prague and nobody is judging. A Trivlu guide books you in so the group just sits and eats. It is the single most effective recovery tool on the itinerary: an hour of serious fuel that resets the group after a big night and sets up whatever the day has planned. Just like they savour it in Ireland, only with Czech beer prices. Come hungry; leave operational.',
        33.00, NULL, 60,
        'https://img.trivlu.com/c1b8bfbe-17e4-40e0-909a-0fda5189935e.webp',
        'Trivlu Guide; Table reservation; 2 Sausage each; 2 Eggs each; 2 Strip of bacon each; 2 Hashbrown each; Black and white pudding each; Tomato each; Mushrooms each; Beans each; Toast each; 2 Beer; juice or soft drink each',
        TRUE, '{"de":{"name":"Full Irish Breakfast","includes":"Trivlu-Guide; Tischreservierung; 2 Würstchen pro Person; 2 Eier pro Person; 2 Streifen Bacon pro Person; 2 Hash Browns pro Person; Black und White Pudding pro Person; Tomate pro Person; Pilze pro Person; Bohnen pro Person; Toast pro Person; 2 Bier, Saft oder Softdrink pro Person","description":"Starte den Tag so, wie ein JGA-Wochenende es verlangt: mit reserviertem Tisch und einem richtigen Full Irish, das schon wartet. Jeder bekommt zwei Würstchen, zwei Eier, zwei Streifen Bacon und zwei Hash Browns, dazu Black und White Pudding, Tomate, Pilze, Bohnen und Toast — und zwei Bier, Saft oder Softdrinks pro Person zum Runterspülen, denn das ist Prag und niemand urteilt. Ein Trivlu-Guide bucht dich ein, die Gruppe setzt sich einfach hin und isst. Das wirksamste Erholungswerkzeug im ganzen Programm: eine Stunde ernsthafter Treibstoff, die die Gruppe nach einer großen Nacht zurücksetzt und alles vorbereitet, was der Tag bringt. Genau wie man es in Irland genießt, nur zu tschechischen Bierpreisen. Komm hungrig; geh einsatzbereit."}}', CURRENT_TIMESTAMP),
       ('59a90ee8-dd8f-46fb-bf5a-a70f6047864b', 'gentlemens-club-night-bar-tab', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Gentlemen''s Club Night + Bar Tab',
        'The full Prague evening, handled end to end. A local Trivlu guide leads your group through the city''s nightlife before landing at one of Prague''s top adult venues, where a VIP table is reserved, entry is covered and each of you has a drinks voucher waiting. From there the night runs itself: table service, a lively venue and no queueing, negotiating or navigating — the guide has already dealt with all of it. Allow around three and a half hours for the full arc. It is the smart way to do a big night in a foreign city: insider access instead of guesswork, a reserved corner instead of a crowd, and a group that ends the evening together instead of scattered across town.',
        60.00, NULL, 217,
        'https://img.trivlu.com/2d7cfb02-d0bc-4198-80cc-fd7b9de81a8a.jpg',
        'Trivlu Guide; Vip Table Reservation; Drinks voucher each; Strip Club Entry',
        TRUE, '{"de":{"name":"Gentlemen''s-Club-Nacht + Bar-Guthaben","includes":"Trivlu-Guide; VIP-Tischreservierung; Getränkegutschein pro Person; Stripclub-Eintritt","description":"Der komplette Prager Abend, von Anfang bis Ende organisiert. Ein lokaler Trivlu-Guide führt deine Gruppe durch das Nachtleben der Stadt, bevor sie in einem der Top-Adult-Venues Prags landet, wo ein VIP-Tisch reserviert ist, der Eintritt bezahlt ist und auf jeden ein Getränkegutschein wartet. Von da an läuft die Nacht von selbst: Tischservice, eine lebendige Location und kein Anstehen, Verhandeln oder Navigieren — der Guide hat sich um alles bereits gekümmert. Plane rund dreieinhalb Stunden für den ganzen Bogen ein. Der clevere Weg für eine große Nacht in einer fremden Stadt: Insider-Zugang statt Raterei, eine reservierte Ecke statt Gedränge und eine Gruppe, die den Abend zusammen beendet, statt über die Stadt verstreut zu sein."}}', CURRENT_TIMESTAMP),
       ('bd2268a8-0158-4d1d-b312-352bdb6766c1', 'gin-tasting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Gin Tasting',
        'A civilised hour before an uncivilised night. This gin tasting seats your group at a reserved table in a private Irish pub, where each of you works through four gin samples with expert insight into what you are drinking and why it tastes the way it does. A Trivlu guide handles the arrangements, and optional food add-ons are available if the group wants a proper base layer before heading out. It is a deliberately relaxed format — closer to a good conversation than a lecture — and it suits the early-evening slot perfectly: everyone arrives, everyone settles, glasses get raised, opinions get confidently wrong. By the time the fourth sample lands, the group has a favourite, a running argument, and exactly the right momentum for the rest of the night.',
        46.00, NULL, 60,
        'https://img.trivlu.com/353e3a4e-cf3a-4f1e-a2f6-b36da44e865c.jpg',
        'Trivlu Guide; Table reservation; 4 glasses Gin for degustation each',
        TRUE, '{"de":{"name":"Gin-Verkostung","includes":"Trivlu-Guide; Tischreservierung; 4 Gläser Gin zur Verkostung pro Person","description":"Eine zivilisierte Stunde vor einer unzivilisierten Nacht. Diese Gin-Verkostung setzt deine Gruppe an einen reservierten Tisch in einem privaten Irish Pub, wo sich jeder durch vier Gin-Proben arbeitet — mit Expertenwissen dazu, was du trinkst und warum es so schmeckt, wie es schmeckt. Ein Trivlu-Guide kümmert sich um die Organisation, und optional gibt es Essen dazu, falls die Gruppe vor dem Ausgehen eine ordentliche Grundlage will. Ein bewusst entspanntes Format — näher an einem guten Gespräch als an einem Vortrag — und perfekt für den Slot am frühen Abend: Alle kommen an, alle richten sich ein, Gläser werden gehoben, Meinungen sind selbstbewusst falsch. Wenn die vierte Probe landet, hat die Gruppe einen Favoriten, eine laufende Diskussion und genau den richtigen Schwung für den Rest der Nacht."}}', CURRENT_TIMESTAMP),
       ('0b1f733a-723c-42a4-8de3-c577ddd424fa', 'go-karting-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Go-Karting Experience',
        'Settle the group''s oldest argument — who is actually the best driver — on a professional go-kart track. The session gives each of you two 10-minute rides, enough for a practice stint and a proper flat-out run at the fastest lap. Private roundtrip transport is included, a Trivlu guide keeps the day moving, and there is a beer each for the podium debate afterwards. Lap times don''t lie, which is precisely what makes karting such a reliable stag do fixture: the confident talkers get found out, the quiet ones spring surprises, and the final classification is argued about for the rest of the weekend. Sharp, quick and competitive, it slots neatly into an afternoon without draining the evening''s energy. Loser wears the result all night.',
        54.00, NULL, 45,
        'https://img.trivlu.com/2825b389-7ff5-47cf-a7f9-4a7885ff8932.png',
        'Trivlu Guide; Private Transport (Roundtrip); 10 min. Go-karting 2 rides each; Beer each',
        TRUE, '{"de":{"name":"Go-Kart-Erlebnis","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); 2 Fahrten à 10 Min. Go-Kart pro Person; Bier pro Person","description":"Kläre den ältesten Streit der Gruppe — wer wirklich der beste Fahrer ist — auf einer professionellen Kartbahn. Die Session gibt jedem zwei 10-minütige Fahrten: genug für eine Übungsrunde und einen richtigen Vollgas-Angriff auf die schnellste Runde. Privater Hin- und Rücktransport ist inklusive, ein Trivlu-Guide hält den Tag in Bewegung, und für die Podiumsdebatte danach gibt es ein Bier pro Person. Rundenzeiten lügen nicht, und genau das macht Kartfahren zu einem so verlässlichen JGA-Fixpunkt: Die selbstbewussten Schwätzer werden entlarvt, die Stillen überraschen, und über die Endwertung wird den Rest des Wochenendes gestritten. Knackig, schnell und kompetitiv fügt es sich sauber in einen Nachmittag ein, ohne die Energie für den Abend zu rauben. Der Verlierer trägt das Ergebnis die ganze Nacht."}}', CURRENT_TIMESTAMP),
       ('ad0fad67-b71a-4bd2-9c37-5f4918c88d55', 'grilled-suckling-pig', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Grilled Suckling Pig',
        'A whole roasted piglet, carried to your table in a historic brewery restaurant in Prague''s city centre — this is a stag do dinner with a sense of theatre. The venue''s Gothic-style interiors and on-site brewed Czech beer set the scene, your table is reserved, and the feast comes with side dishes plus two large beers per person. A Trivlu guide books the group in and gets you settled. Allow around two and a half hours: carving a suckling pig between mates is not a meal to rush, and the room''s atmosphere rewards a long sitting. It is the anchor dinner of a Prague weekend — hearty enough to fuel a full night out, memorable enough that the photos become the trip''s centrepiece, and unapologetically Czech from first pour to last rib.',
        51.00, NULL, 128,
        'https://img.trivlu.com/ade3509b-8617-419d-91b4-a05f10ca94fa.jpg',
        'Trivlu Guide; Table reservation; Grilled Piglet; Side Dishes; 2 Large Beers/Person',
        TRUE, '{"de":{"name":"Gegrilltes Spanferkel","includes":"Trivlu-Guide; Tischreservierung; Gegrilltes Spanferkel; Beilagen; 2 große Biere pro Person","description":"Ein ganzes gebratenes Ferkel, an deinen Tisch in einem historischen Brauereirestaurant im Zentrum Prags getragen — ein JGA-Dinner mit Sinn für Theater. Die gotisch inspirierten Räume der Location und das vor Ort gebraute tschechische Bier setzen die Szene, dein Tisch ist reserviert, und das Festmahl kommt mit Beilagen plus zwei großen Bieren pro Person. Ein Trivlu-Guide bucht die Gruppe ein und bringt alle unter. Plane rund zweieinhalb Stunden ein: Ein Spanferkel unter Kumpels zu tranchieren ist keine Mahlzeit zum Hetzen, und die Atmosphäre des Raums belohnt ein langes Sitzen. Das Anker-Dinner eines Prag-Wochenendes — deftig genug für eine ganze Nacht, denkwürdig genug, dass die Fotos zum Herzstück der Reise werden, und kompromisslos tschechisch vom ersten Schluck bis zur letzten Rippe."}}', CURRENT_TIMESTAMP),
       ('f7b4b3e0-ff03-4641-ad58-5ed9b4784f43', 'guided-cabaret-club-tour', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Guided Cabaret Club Tour',
        'Prague''s nightlife with someone who actually knows the map. This two-hour guided night out takes your group through a free selection of bars with a local Trivlu guide sharing the tips that never make it into guidebooks, then finishes with entry to one of the city''s top cabaret clubs — free entry to selected venues along the way included. No cover-charge roulette, no wrong turns, no standing in lines that lead nowhere. It is the ideal first-night format: you find out where the good rooms are, the guide handles every door, and the group builds momentum stop by stop. By the time you reach the final venue, the night is already a success — everything after that is a bonus.',
        10.00, 70.00, 120,
        'https://img.trivlu.com/8b0a9a19-ca9b-40d5-bf63-da747326ac70.jpg',
        'Trivlu Guide; Strip Club Entry; Guided tour through Prague; Free selection of bars to visit; Local tips; Free entry to chosen clubs in Prague',
        TRUE, '{"de":{"name":"Geführte Tour im Cabaret-Club","includes":"Trivlu-Guide; Stripclub-Eintritt; Geführte Tour durch Prag; Freie Auswahl an Bars; Lokale Tipps; Freier Eintritt in ausgewählte Clubs in Prag","description":"Prags Nachtleben mit jemandem, der den Stadtplan wirklich kennt. Dieser zweistündige geführte Abend führt deine Gruppe durch eine freie Auswahl an Bars, während ein lokaler Trivlu-Guide die Tipps teilt, die es nie in Reiseführer schaffen, und endet mit dem Eintritt in einen der Top-Cabaret-Clubs der Stadt — freier Eintritt in ausgewählte Locations unterwegs inklusive. Kein Eintrittspreis-Roulette, keine falschen Abzweigungen, kein Anstehen in Schlangen, die nirgendwohin führen. Das ideale Format für die erste Nacht: Du findest heraus, wo die guten Läden sind, der Guide regelt jede Tür, und die Gruppe baut Stopp für Stopp Schwung auf. Wenn du die letzte Location erreichst, ist die Nacht bereits ein Erfolg — alles danach ist Bonus."}}', CURRENT_TIMESTAMP),
       ('9e7e8bb5-3058-4110-ac56-5065be21c919', 'hangover-brunch', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Hangover Brunch',
        'The morning after has a fix, and it involves maple syrup and mimosas. Hangover Brunch reserves your group a table for 90 minutes of serious recovery: pancakes with Nutella and fresh strawberries, poached egg with parmesan on avocado toast, waffles with warm berry compote and cream, French toast with crispy bacon and maple syrup, and a bowl of fruit oats for anyone claiming virtue. For a full hour, beer, wine and mimosas are unlimited — hair of the dog, administered properly. A Trivlu guide books it all so nobody has to make decisions before noon. It is the smartest slot on a stag itinerary: the group reassembles, last night''s stories get their first retelling, and everyone walks out ready for round two. Prague forgives, brunch restores.',
        73.00, NULL, 90,
        'https://img.trivlu.com/8cb58e0f-a0e7-4168-8811-cd8168fcb55d.webp',
        'Trivlu Guide; Table reservation; hour of unlimited Beer; Wine & Mimosa; Pancakes with nutella and fresh strawberries; Poached egg topped with parmesan on avocado toast; Waffles with warm berry compote and fresh cream; French toast with crispy bacon and maple syrup; Bowl of fruit oats',
        TRUE, '{"de":{"name":"Kater-Brunch","includes":"Trivlu-Guide; Tischreservierung; Eine Stunde unbegrenzt Bier, Wein & Mimosa; Pancakes mit Nutella und frischen Erdbeeren; Pochiertes Ei mit Parmesan auf Avocado-Toast; Waffeln mit warmem Beerenkompott und frischer Sahne; French Toast mit knusprigem Bacon und Ahornsirup; Schale Früchte-Haferflocken","description":"Für den Morgen danach gibt es eine Lösung, und sie beinhaltet Ahornsirup und Mimosas. Der Kater-Brunch reserviert deiner Gruppe einen Tisch für 90 Minuten ernsthafte Erholung: Pancakes mit Nutella und frischen Erdbeeren, pochiertes Ei mit Parmesan auf Avocado-Toast, Waffeln mit warmem Beerenkompott und Sahne, French Toast mit knusprigem Bacon und Ahornsirup, und eine Schale Früchte-Haferflocken für alle, die Tugend vortäuschen. Eine volle Stunde lang sind Bier, Wein und Mimosas unbegrenzt — Konterbier, fachgerecht verabreicht. Ein Trivlu-Guide bucht alles, damit niemand vor Mittag Entscheidungen treffen muss. Der cleverste Slot im JGA-Programm: Die Gruppe sammelt sich wieder, die Geschichten der letzten Nacht werden zum ersten Mal erzählt, und alle gehen bereit für Runde zwei raus. Prag vergibt, der Brunch stellt wieder her."}}', CURRENT_TIMESTAMP),
       ('d61d984e-2a61-4f1a-ac3b-5567925a2c1b', 'hummer-limo', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Hummer Limo',
        'Arrive everywhere like you mean it. The Hummer limo experience gives your group a full hour''s ride through Prague with a driver at the wheel, music and lights running, and bottles of bubbly included to set the tone. Use it as a rolling party between nightlife spots, a grand entrance to the evening''s main venue, or simply an hour of cruising the city while the group gets loud. It is the classic stag do statement piece: zero effort, maximum arrival value, and the rare activity where the transport is the event. The stag rides up front in every photo, the bubbly disappears fast, and by the time the door opens outside the club, the night already has momentum. One hour, one very big car, one unmissable entrance.',
        55.00, 470.00, 60,
        'https://img.trivlu.com/2814a2b0-5171-4d14-86f7-18733aac1e80.jpg',
        'Bottles of Bubbly; Driver; 1 Hour Ride or Transfer',
        TRUE, '{"de":{"name":"Hummer-Limousine","includes":"Flaschen Sekt; Fahrer; 1 Stunde Fahrt oder Transfer","description":"Komm überall so an, als wäre es dir ernst. Das Hummer-Limousinen-Erlebnis gibt deiner Gruppe eine volle Stunde Fahrt durch Prag — mit Fahrer am Steuer, Musik und Licht an und Flaschen Sekt inklusive, um den Ton zu setzen. Nutze es als rollende Party zwischen den Nachtleben-Stopps, als großen Auftritt vor der Haupt-Location des Abends oder einfach als Stunde Cruisen durch die Stadt, während die Gruppe laut wird. Das klassische JGA-Statement: null Aufwand, maximaler Auftritt und die seltene Aktivität, bei der der Transport das Event ist. Der Bräutigam sitzt auf jedem Foto vorne, der Sekt verschwindet schnell, und wenn sich die Tür vor dem Club öffnet, hat die Nacht bereits Schwung. Eine Stunde, ein sehr großes Auto, ein unvergesslicher Auftritt."}}', CURRENT_TIMESTAMP),
       ('acf04a55-dc77-4654-b8bb-a776e52e6f89', 'jelly-wrestling', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Jelly Wrestling',
        'Exactly as ridiculous as it sounds, and twice as entertaining. Jelly Wrestling puts your group ringside at a Prague club for a gloriously messy spectacle: two professional performers, a 10-minute show, then 10 minutes of wrestling in a pool of jelly — with a round in the pool reserved for the stag himself, because of course there is. Club entry, a drink and a beer each are included, and showers and towels are waiting for the participants afterwards. A Trivlu guide arranges the whole thing. It is 45 minutes of pure stag do theatre: loud, absurd, impossible to describe with a straight face and captured on a dozen phones from the first second. The stag emerges clean; his reputation does not.',
        40.00, 463.00, 45,
        'https://img.trivlu.com/b4e17a6d-895c-4d11-b006-d537ece86a38.jpg',
        'Trivlu Guide; Drink(s) each; 2 Strippers; 10 min. Lesbian Show; 10 min. Wrestling; Shower & Towels; Strip Club Entry round Stag in the Pool; Beer each',
        TRUE, '{"de":{"name":"Jelly Wrestling","includes":"Trivlu-Guide; Drink pro Person; 2 Stripperinnen; 10 Min. Lesben-Show; 10 Min. Wrestling; Dusche & Handtücher; Stripclub-Eintritt, Runde für den Bräutigam im Pool; Bier pro Person","description":"Genau so lächerlich, wie es klingt, und doppelt so unterhaltsam. Jelly Wrestling setzt deine Gruppe in einem Prager Club an den Ring für ein herrlich schmutziges Spektakel: zwei professionelle Performerinnen, eine 10-minütige Show, dann 10 Minuten Wrestling in einem Pool voller Wackelpudding — mit einer Runde im Pool, die für den Bräutigam selbst reserviert ist, versteht sich. Club-Eintritt, ein Drink und ein Bier pro Person sind inklusive, und für die Teilnehmer warten danach Duschen und Handtücher. Ein Trivlu-Guide organisiert das Ganze. 45 Minuten pures JGA-Theater: laut, absurd, unmöglich mit ernstem Gesicht zu beschreiben und von der ersten Sekunde an auf einem Dutzend Handys festgehalten. Der Bräutigam kommt sauber raus — sein Ruf nicht."}}', CURRENT_TIMESTAMP),
       ('f7d39296-3346-4e63-807f-75c3f63d846e', 'lamborghini-ride', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Lamborghini Ride',
        'Some bucket-list items are best ticked in Prague. This experience puts you in a Lamborghini Gallardo LP560-4 for a 30-minute high-speed run on the highway with a professional driver — full soundtrack, proper acceleration, zero speeding tickets in your name. Private roundtrip transport gets the group to the start point, pictures and videos are included so the moment is properly documented, and a Trivlu guide manages the day. Allow around 90 minutes all in. As a stag do activity it is pure indulgence: the petrolheads get their fix, the stag gets his hero moment, and the group gets footage that upgrades every future retelling of the weekend. Supercars, like stag weekends, are wasted on the sensible — book the ride and let the V10 do the talking.',
        80.00, NULL, 90,
        'https://img.trivlu.com/77f1dfbf-e5ad-4c36-910f-74bc5997ecfa.avif',
        'Trivlu Guide; Private Transport (Roundtrip); 30 min. Ride with Professional Driver; Pictures and videos',
        TRUE, '{"de":{"name":"Lamborghini-Fahrt","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); 30 Min. Fahrt mit professionellem Fahrer; Fotos und Videos","description":"Manche Bucket-List-Punkte hakt man am besten in Prag ab. Dieses Erlebnis setzt dich in einen Lamborghini Gallardo LP560-4 für eine 30-minütige Highspeed-Fahrt auf der Autobahn mit professionellem Fahrer — voller Sound, richtige Beschleunigung, null Strafzettel auf deinen Namen. Privater Hin- und Rücktransport bringt die Gruppe zum Startpunkt, Fotos und Videos sind inklusive, damit der Moment ordentlich dokumentiert ist, und ein Trivlu-Guide managt den Tag. Plane insgesamt rund 90 Minuten ein. Als JGA-Aktivität ist es purer Luxus: Die Benzinköpfe bekommen ihren Kick, der Bräutigam seinen Heldenmoment, und die Gruppe Filmmaterial, das jede künftige Nacherzählung des Wochenendes aufwertet. Supersportwagen sind, wie JGA-Wochenenden, an die Vernünftigen verschwendet — buche die Fahrt und lass den V10 reden."}}', CURRENT_TIMESTAMP),
       ('bd7b9331-8eaf-4db2-99ba-bac4ced7cadf', 'laser-tag', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Laser Tag',
        'Thirty minutes of playing time, a 300 m² futuristic maze, and every friendship in the group temporarily suspended. Laser tag in Prague runs as two fast 15-minute games — play solo or split into teams — with all equipment provided and a beer or soft drink each waiting at the end. A Trivlu guide gets the group in and set up. It is paintball-style action without the bruises or the laundry bill: fast, sweaty and ruthlessly score-driven, which makes it perfect stag do material. The maze rewards sneaks over sprinters, so the group''s least athletic member frequently ends up topping the leaderboard, and the scoreboard printout ends the argument the moment it starts. An easy city-centre hit that fits any gap in the itinerary.',
        40.00, NULL, 60,
        'https://img.trivlu.com/37e1a944-bbf6-4b89-a0f9-1864910bb34a.jpg',
        'Trivlu Guide; 30 min. Playing Time; Equipment & Safety Gear; Beer(s) or Soft Drink(s) each',
        TRUE, '{"de":{"name":"Lasertag","includes":"Trivlu-Guide; 30 Min. Spielzeit; Ausrüstung & Schutzausrüstung; Bier oder Softdrink pro Person","description":"Dreißig Minuten Spielzeit, ein 300 m² großes futuristisches Labyrinth und jede Freundschaft in der Gruppe vorübergehend ausgesetzt. Lasertag in Prag läuft als zwei schnelle 15-Minuten-Spiele — solo oder in Teams — mit kompletter Ausrüstung und einem Bier oder Softdrink pro Person am Ende. Ein Trivlu-Guide bringt die Gruppe rein und richtet alles ein. Paintball-Action ohne blaue Flecken und Wäscherechnung: schnell, schweißtreibend und gnadenlos punktegetrieben — perfektes JGA-Material. Das Labyrinth belohnt Schleicher mehr als Sprinter, deshalb landet der unsportlichste der Gruppe erstaunlich oft ganz oben, und der Ausdruck der Rangliste beendet jeden Streit, bevor er beginnt. Ein einfacher Hit im Stadtzentrum, der in jede Lücke im Programm passt."}}', CURRENT_TIMESTAMP),
       ('28a12bb5-1eb7-457b-8476-e35e682a1ef7', 'live-music-irish-dinner', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Live Music Irish Dinner',
        'Launch the weekend the Irish way: live music, a reserved table and platters that never seem to end. This two-hour dinner brings your group marinated steak strips, chicken wings, calamari, chips, potato wedges, onion rings, mozzarella sticks and garlic bread — all served to share — with three beers each and a live Irish band providing the soundtrack. A Trivlu guide books the group in and gets the night moving. Shared platters are the right call for a stag table: everyone grazes, nobody waits, and the conversation never has to pause for cutlery logistics. Add music with actual energy and you have the ideal first-night anchor — hearty enough to set up a long evening, lively enough that the party starts at the dinner table rather than after it.',
        41.00, NULL, 120,
        'https://img.trivlu.com/2fb4449f-7f8f-40ae-b9e2-b9fc19ebf699.webp',
        'Trivlu Guide; Live Irish music; Table reservation; 3 Beer each; Marinated steak strips (shared on a platter); Chicken wings (shared on a platter); Calamari (shared on a platter); Chips (shared on a platter); Potato wedges (shared on a platter); Onion rings (shared on a platter); Mozzarella sticks (shared on a platter); Garlic bread',
        TRUE, '{"de":{"name":"Irisches Dinner mit Live-Musik","includes":"Trivlu-Guide; Irische Live-Musik; Tischreservierung; 3 Bier pro Person; Marinierte Steakstreifen (Platte zum Teilen); Chicken Wings (Platte zum Teilen); Calamari (Platte zum Teilen); Pommes (Platte zum Teilen); Kartoffelspalten (Platte zum Teilen); Zwiebelringe (Platte zum Teilen); Mozzarella-Sticks (Platte zum Teilen); Knoblauchbrot","description":"Starte das Wochenende auf irische Art: Live-Musik, ein reservierter Tisch und Platten, die nie enden wollen. Dieses zweistündige Dinner bringt deiner Gruppe marinierte Steakstreifen, Chicken Wings, Calamari, Pommes, Kartoffelspalten, Zwiebelringe, Mozzarella-Sticks und Knoblauchbrot — alles zum Teilen serviert — mit drei Bier pro Person und einer irischen Live-Band als Soundtrack. Ein Trivlu-Guide bucht die Gruppe ein und bringt den Abend ins Rollen. Platten zum Teilen sind die richtige Wahl für einen JGA-Tisch: Alle picken, niemand wartet, und das Gespräch muss nie für Besteck-Logistik pausieren. Dazu Musik mit echter Energie, und du hast den idealen Anker für die erste Nacht — deftig genug für einen langen Abend, lebendig genug, dass die Party schon am Esstisch beginnt statt danach."}}', CURRENT_TIMESTAMP),
       ('f93a58bb-e43f-410d-9ffe-b24af7ce70e7', 'maid-service-prank-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Maid Service Prank Show',
        'The shortest booking on the list and one of the most talked about afterwards. The Maid Service Prank Show starts innocently: maids arrive to clean the room. Twenty minutes later the stag has been the centrepiece of a cheeky adult comedy performance by two professional artists, the group has cried laughing, and the weekend has its opening story. A Trivlu guide sets up the timing so the surprise is airtight — the only requirement is a stag who suspects nothing. It works brilliantly as a morning hangover cure or as the ambush that opens the first evening. Twenty minutes, two performers, one completely blindsided groom: maximum effect per minute of any prank in Prague.',
        36.00, 240.00, 20,
        'https://img.trivlu.com/5c82afc2-02fe-4029-9703-52461b652fbb.jpg',
        'Trivlu Guide; 20 min. Lesbian Show',
        TRUE, '{"de":{"name":"Zimmermädchen-Prank-Show","includes":"Trivlu-Guide; 20 Min. Lesben-Show","description":"Die kürzeste Buchung auf der Liste und eine der meistbesprochenen danach. Die Zimmermädchen-Prank-Show beginnt harmlos: Zimmermädchen kommen, um das Zimmer zu putzen. Zwanzig Minuten später war der Bräutigam Mittelpunkt einer frechen Erwachsenen-Comedy-Performance von zwei professionellen Künstlerinnen, die Gruppe hat Tränen gelacht, und das Wochenende hat seine Eröffnungsgeschichte. Ein Trivlu-Guide stimmt das Timing ab, damit die Überraschung wasserdicht ist — die einzige Voraussetzung ist ein Bräutigam, der nichts ahnt. Funktioniert brillant als morgendliches Katermittel oder als Hinterhalt zum Auftakt des ersten Abends. Zwanzig Minuten, zwei Performerinnen, ein völlig überrumpelter Bräutigam: maximale Wirkung pro Minute unter allen Pranks in Prag."}}', CURRENT_TIMESTAMP),
       ('e9d0c862-01d5-4842-be51-40a8d60a5a56', 'medieval-dinner', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Medieval Dinner',
        'Go back a few centuries for the night. The Medieval Dinner seats your group at a reserved table in a lively tavern setting for a feast of genuinely absurd scale: cheese and sausage platters, chicken steak, pork neck, pork knuckle with horseradish and mustard, meat skewers, chicken wings, marinated pork ribs, sauces, bread, baked potatoes, grilled vegetables and homemade apple pie — with unlimited beer, wine and soft drinks throughout. A medieval show with music and live entertainment runs as you eat, and a Trivlu guide handles the booking. It is dinner as spectacle: food you tear rather than slice, and a table that looks like a victory banquet. For stag groups it is the easiest wow of the weekend — nobody forgets the night the pork knuckles arrived.',
        89.00, NULL, 120,
        'https://img.trivlu.com/7be4a643-e1cc-4965-b048-ed97223ded25.jpg',
        'Trivlu Guide; Table reservation; 180 min. Medieval Show; Cheese platter; Sausage Platter; Chicken steak; Pork neck; Pork knuckle with horseradish and mustard; Meat skewer; Chicken Wings each; Marinated pork ribs; Various sauces; Bread; baked potatoes; Grilled vegetable; Homemade Apple pie; Unlimited Beer; Wine & Soft Drinks',
        TRUE, '{"de":{"name":"Mittelalterliches Dinner","includes":"Trivlu-Guide; Tischreservierung; 180 Min. Mittelalter-Show; Käseplatte; Wurstplatte; Hähnchensteak; Schweinenacken; Schweinshaxe mit Meerrettich und Senf; Fleischspieß; Chicken Wings pro Person; Marinierte Schweinerippchen; Verschiedene Saucen; Brot; Ofenkartoffeln; Gegrilltes Gemüse; Hausgemachter Apfelkuchen; Unbegrenzt Bier, Wein & Softdrinks","description":"Reise für einen Abend ein paar Jahrhunderte zurück. Das mittelalterliche Dinner setzt deine Gruppe an einen reservierten Tisch in einer lebhaften Taverne für ein Festmahl von wahrhaft absurdem Ausmaß: Käse- und Wurstplatten, Hähnchensteak, Schweinenacken, Schweinshaxe mit Meerrettich und Senf, Fleischspieße, Chicken Wings, marinierte Schweinerippchen, Saucen, Brot, Ofenkartoffeln, gegrilltes Gemüse und hausgemachter Apfelkuchen — mit unbegrenzt Bier, Wein und Softdrinks die ganze Zeit. Während du isst, läuft eine Mittelalter-Show mit Musik und Live-Unterhaltung, und ein Trivlu-Guide kümmert sich um die Buchung. Dinner als Spektakel: Essen, das man reißt statt schneidet, und ein Tisch, der wie ein Siegesbankett aussieht. Für JGA-Gruppen der einfachste Wow-Moment des Wochenendes — niemand vergisst die Nacht, in der die Schweinshaxen kamen."}}', CURRENT_TIMESTAMP),
       ('e294bbbd-d52f-4cb1-b56f-284967638328', 'meet-greet-in-prague', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Meet & Greet in Prague',
        'The weekend starts the moment you land — so start it without confusion. With Meet & Greet, a local Trivlu guide is waiting for your group at Prague airport on arrival, public transport tickets in hand, and walks you straight through the quickest route to your accommodation. Along the way you get the local briefing that actually matters: which neighbourhoods to drink in, what a beer should cost, how the transport works and what to avoid late at night. It is the unglamorous booking that quietly upgrades the whole trip, especially for the trip organiser — no taxi negotiations, no group scattered across arrivals, no first-hour chaos. One hour, zero stress, and the stag weekend begins with everyone in the same place, on time, already armed with insider knowledge.',
        12.00, 50.00, 60,
        'https://img.trivlu.com/834ffe21-ac3a-4387-b232-2d83cfdab2bc.jpg',
        'Trivlu Guide; Public Transport tickets',
        TRUE, '{"de":{"name":"Meet & Greet in Prag","includes":"Trivlu-Guide; Tickets für öffentliche Verkehrsmittel","description":"Das Wochenende beginnt in dem Moment, in dem du landest — also beginnt es ohne Verwirrung. Beim Meet & Greet wartet ein lokaler Trivlu-Guide bei der Ankunft am Prager Flughafen auf deine Gruppe, Tickets für die öffentlichen Verkehrsmittel in der Hand, und führt dich auf dem schnellsten Weg direkt zu deiner Unterkunft. Unterwegs bekommst du das lokale Briefing, das wirklich zählt: in welchen Vierteln man trinkt, was ein Bier kosten sollte, wie der Nahverkehr funktioniert und was man spätnachts meiden sollte. Die unglamouröse Buchung, die die ganze Reise still aufwertet — besonders für den Organisator: keine Taxi-Verhandlungen, keine über die Ankunftshalle verstreute Gruppe, kein Chaos in der ersten Stunde. Eine Stunde, null Stress, und das JGA-Wochenende beginnt mit allen am selben Ort, pünktlich und bereits mit Insiderwissen bewaffnet."}}', CURRENT_TIMESTAMP),
       ('00487452-a65e-4a5c-bd23-23e607825fe3', 'middle-east-dinner', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Middle east dinner (Vegan options available)',
        'A change of pace from pork and pilsner. This 90-minute dinner books your group a table at a local Middle Eastern restaurant for a traditional spread — generous shared platters, rich spices and the kind of warm, social atmosphere that turns a meal into an event. Two beers each are included, vegan options are available, and a Trivlu guide arranges everything so the group just sits down and starts passing dishes. Sharing-style dining is quietly perfect for stag groups: the table stays lively, everyone tries everything, and the food keeps arriving while the stories do the same. It works beautifully as a first-night dinner or a mid-weekend break from Czech classics — big flavours, easy logistics, and a full table that sets the group up properly for the night ahead.',
        60.00, NULL, 90,
        'https://img.trivlu.com/318ec868-852f-4d73-bf88-fd630021ca3f.png',
        'Trivlu Guide; Table in Local middle east restaurant; traditional middle east dinner; 2 beers each',
        TRUE, '{"de":{"name":"Orientalisches Dinner (vegane Optionen verfügbar)","includes":"Trivlu-Guide; Tisch in lokalem orientalischem Restaurant; Traditionelles orientalisches Dinner; 2 Bier pro Person","description":"Ein Tempowechsel nach Schwein und Pils. Dieses 90-minütige Dinner bucht deiner Gruppe einen Tisch in einem lokalen orientalischen Restaurant für ein traditionelles Festmahl — großzügige Platten zum Teilen, reiche Gewürze und die Art warmer, geselliger Atmosphäre, die aus einer Mahlzeit ein Event macht. Zwei Bier pro Person sind inklusive, vegane Optionen verfügbar, und ein Trivlu-Guide organisiert alles, damit sich die Gruppe einfach hinsetzt und Schüsseln weiterreicht. Essen zum Teilen ist still und heimlich perfekt für JGA-Gruppen: Der Tisch bleibt lebendig, jeder probiert alles, und das Essen kommt genauso nach wie die Geschichten. Wunderbar als Dinner am ersten Abend oder als Pause von den tschechischen Klassikern mitten im Wochenende — große Aromen, einfache Logistik und ein voller Tisch, der die Gruppe richtig auf die Nacht vorbereitet."}}', CURRENT_TIMESTAMP),
       ('44798a57-3c6d-4be4-bd88-8590970db27b', 'nyotaimori-sushi-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Nyotaimori Sushi Experience',
        'Nyotaimori — the Japanese tradition of sushi served on a live model — meets a Prague stag night. In a private room your group gathers around the most memorable dinner table of the weekend: a full sushi body buffet, served the traditional way, with a drink each and adult venue entry included afterwards. A Trivlu guide arranges the room and the evening''s flow. It is a booking for groups that want their big night to open with something genuinely different — part dinner, part spectacle, entirely unforgettable. The format rewards a bit of decorum (chopsticks, patience, appreciation of craft) before the night dissolves into the usual chaos. Bold, private and unlike anything else on the Prague list.',
        110.00, NULL, 60,
        'https://img.trivlu.com/72255dc6-5b9c-4e21-9a17-f574d24d94c5.jpg',
        'Trivlu Guide; Private Room; Sushi Body Buffet; Drink(s) each; Strip Club Entry',
        TRUE, '{"de":{"name":"Nyotaimori-Sushi-Erlebnis","includes":"Trivlu-Guide; Privater Raum; Sushi-Body-Buffet; Drink pro Person; Stripclub-Eintritt","description":"Nyotaimori — die japanische Tradition, Sushi auf einem lebenden Model zu servieren — trifft auf eine Prager JGA-Nacht. In einem privaten Raum versammelt sich deine Gruppe um den denkwürdigsten Esstisch des Wochenendes: ein komplettes Sushi-Body-Buffet, traditionell serviert, mit einem Drink pro Person und anschließendem Eintritt in ein Adult-Venue inklusive. Ein Trivlu-Guide organisiert den Raum und den Ablauf des Abends. Eine Buchung für Gruppen, die ihre große Nacht mit etwas wirklich anderem eröffnen wollen — halb Dinner, halb Spektakel, ganz unvergesslich. Das Format belohnt ein bisschen Anstand (Stäbchen, Geduld, Wertschätzung des Handwerks), bevor sich die Nacht ins übliche Chaos auflöst. Mutig, privat und anders als alles andere auf der Prag-Liste."}}', CURRENT_TIMESTAMP),
       ('626e9c80-5e3d-4d78-bf77-85305380243c', 'one-way-airport-transfer-prague', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'One Way Airport Transfer Prague',
        'The least glamorous booking of the weekend is also the one you will be most grateful for. This one-way airport transfer puts a professional driver and private transport at your group''s disposal, taking you straight from Prague airport to your accommodation with zero negotiation, zero splitting into confused taxi factions, and zero chance of the weekend starting with an argument about directions. A Trivlu guide coordinates the pickup so the driver is there when you land, not twenty minutes after. For the organiser it removes the single most error-prone hour of the trip; for everyone else it means the first Czech beer arrives sooner. Simple, comfortable and door to door — exactly what you want after a flight and exactly what you will not want to arrange at the terminal.',
        15.00, NULL, 60,
        'https://img.trivlu.com/63ecafa7-2ba7-4c84-adc0-77bb936f89e9.jpeg',
        'Trivlu Guide; Private Transport (One-way)',
        TRUE, '{"de":{"name":"Einfacher Flughafentransfer Prag","includes":"Trivlu-Guide; Privater Transport (einfache Fahrt)","description":"Die unglamouröseste Buchung des Wochenendes ist auch die, für die du am dankbarsten sein wirst. Dieser einfache Flughafentransfer stellt deiner Gruppe einen professionellen Fahrer und privaten Transport zur Verfügung und bringt dich direkt vom Prager Flughafen zur Unterkunft — ohne Verhandeln, ohne Aufteilung in verwirrte Taxi-Fraktionen und ohne die Gefahr, dass das Wochenende mit einem Streit über den Weg beginnt. Ein Trivlu-Guide koordiniert die Abholung, damit der Fahrer da ist, wenn du landest, und nicht zwanzig Minuten später. Für den Organisator entfällt die fehleranfälligste Stunde der Reise; für alle anderen kommt das erste tschechische Bier früher. Einfach, bequem und von Tür zu Tür — genau das, was man nach einem Flug will, und genau das, was man am Terminal nicht organisieren möchte."}}', CURRENT_TIMESTAMP),
       ('dbc5a2c2-96cd-40c5-9eed-5fdf3fcaf63d', 'paintball', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Paintball',
        'Two hundred paintballs each, camo on, scores to settle. This year-round paintball session near Prague runs fast-paced team battles with a qualified instructor in charge, full equipment and safety gear provided, and a costume for the stag so he is impossible to miss on the field — by design. Private roundtrip transport is included, there is a beer for each player when the ammunition runs dry, and a Trivlu guide manages the whole outing. Paintball earns its place on every stag list for a reason: strategy matters just enough to argue about, betrayal is inevitable, and 200 rounds is precisely the right amount to resolve every grudge the group has accumulated. Two hours of adrenaline, bruised pride, and one heavily decorated groom. Plan it for the day; celebrate the survivors at night.',
        37.00, NULL, 120,
        'https://img.trivlu.com/27cce4c5-bf5e-4d00-8b44-9a02ba9a7bc7.webp',
        'Trivlu Guide; Private Transport (Roundtrip); Equipment & Safety Gear; Qualified Instructor; Costume for Stag or Hen; Beer each; 200 paintballs each',
        TRUE, '{"de":{"name":"Paintball","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Ausrüstung & Schutzausrüstung; Qualifizierter Instruktor; Kostüm für Bräutigam oder Braut; Bier pro Person; 200 Paintballs pro Person","description":"Zweihundert Paintballs pro Person, Tarnanzug an, Rechnungen zu begleichen. Diese ganzjährige Paintball-Session bei Prag bietet rasante Teamkämpfe mit qualifiziertem Instruktor, kompletter Ausrüstung und Schutzausrüstung und einem Kostüm für den Bräutigam, damit er auf dem Feld unmöglich zu übersehen ist — mit Absicht. Privater Hin- und Rücktransport ist inklusive, es gibt ein Bier für jeden Spieler, wenn die Munition ausgeht, und ein Trivlu-Guide managt den gesamten Ausflug. Paintball hat sich seinen Platz auf jeder JGA-Liste verdient: Strategie zählt gerade genug, um darüber zu streiten, Verrat ist unvermeidlich, und 200 Schuss sind genau die richtige Menge, um jeden Groll zu klären, den die Gruppe angesammelt hat. Zwei Stunden Adrenalin, verletzter Stolz und ein reich dekorierter Bräutigam. Plane es für den Tag; feiere die Überlebenden in der Nacht."}}', CURRENT_TIMESTAMP),
       ('c73644b6-2232-42f3-b807-5c242cc055fe', 'party-limo-ride', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Party Limo Ride',
        'A full hour through Prague in a stretch limousine, and the party starts the moment the doors close. The Party Limo Ride comes with a driver, a bottle of bubbly for the group, music and lights — and a 15-minute onboard show performance that turns the ride itself into the first event of the night. Use it as a rolling pre-party, a headline transfer between venues, or the stag''s grand entrance to the evening. A Trivlu guide coordinates the pickup. It is the upgrade on an ordinary limo booking: same stylish arrival, same skyline slipping past the windows, but with entertainment on board that guarantees the group walks out already buzzing. One hour, one very long car, zero slow starts.',
        47.00, 350.00, 60,
        'https://img.trivlu.com/5bcd6622-50f3-4cb0-9ee9-53a10311e174.jpg',
        'Trivlu Guide; Bottle of Bubbly; 15 min. Strip Show; Driver; 1 Hour Ride or Transfer',
        TRUE, '{"de":{"name":"Party-Limo-Fahrt","includes":"Trivlu-Guide; Flasche Sekt; 15 Min. Stripshow; Fahrer; 1 Stunde Fahrt oder Transfer","description":"Eine volle Stunde durch Prag in einer Stretchlimousine, und die Party beginnt in dem Moment, in dem sich die Türen schließen. Die Party-Limo-Fahrt kommt mit Fahrer, einer Flasche Sekt für die Gruppe, Musik und Licht — und einer 15-minütigen Show an Bord, die die Fahrt selbst zum ersten Event der Nacht macht. Nutze sie als rollende Pre-Party, als Headliner-Transfer zwischen den Locations oder als großen Auftritt des Bräutigams zum Abend. Ein Trivlu-Guide koordiniert die Abholung. Das Upgrade zur gewöhnlichen Limo-Buchung: derselbe stilvolle Auftritt, dieselbe Skyline, die an den Fenstern vorbeizieht, aber mit Unterhaltung an Bord, die garantiert, dass die Gruppe schon aufgedreht aussteigt. Eine Stunde, ein sehr langes Auto, null langsamer Start."}}', CURRENT_TIMESTAMP),
       ('bef3fb1e-76ea-401a-8794-ee0f8fea942f', 'party-starter-on-terrace', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Party Starter On Terrace',
        'Every big night needs ignition. Party Starter on Terrace reserves your group a table in Prague''s city centre for two hours of unlimited beer, with eight shots each to accelerate proceedings and views to remind you why you flew here. A Trivlu guide gets everyone seated and the first round moving. The format is gloriously simple: no schedule, no activity to master, just the group, a terrace and a steadily improving atmosphere as the city lights up below. It is the ideal bridge between dinner and nightlife — momentum builds, toasts get made, plans get louder — and by the time the two hours are up, the group is unanimously ready for whatever comes next. Start high, in every sense, and let the evening roll downhill from there.',
        107.00, NULL, 120,
        'https://img.trivlu.com/83dd8daf-e2dd-43e2-b75d-c284c942dd83.jpg',
        'Trivlu Guide; Table reservation; 8 Shot each; 2 hrs. Unlimited beer',
        TRUE, '{"de":{"name":"Party-Starter auf der Terrasse","includes":"Trivlu-Guide; Tischreservierung; 8 Shots pro Person; 2 Std. unbegrenzt Bier","description":"Jede große Nacht braucht Zündung. Party-Starter auf der Terrasse reserviert deiner Gruppe einen Tisch im Zentrum Prags für zwei Stunden unbegrenzt Bier, mit acht Shots pro Person, um das Tempo anzuziehen, und Aussicht, die dich daran erinnert, warum du hergeflogen bist. Ein Trivlu-Guide bringt alle an den Tisch und die erste Runde in Gang. Das Format ist herrlich einfach: kein Zeitplan, keine Aktivität zu meistern, nur die Gruppe, eine Terrasse und eine stetig besser werdende Stimmung, während unter dir die Stadt aufleuchtet. Die ideale Brücke zwischen Dinner und Nachtleben — der Schwung wächst, Toasts werden ausgesprochen, Pläne werden lauter — und wenn die zwei Stunden um sind, ist die Gruppe einstimmig bereit für alles, was kommt. Starte hoch, in jeder Hinsicht, und lass den Abend von dort bergab rollen."}}', CURRENT_TIMESTAMP),
       ('77c62df8-f6e7-4718-a7fb-41758346cdbb', 'pitbikes-racing', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Pitbikes Racing',
        'Proper motorsport, shrunk to stag size. Pitbikes Racing takes your group to a purpose-built off-road track near Prague — private roundtrip transport included — and kits each rider out head to toe: integral helmet, leather overall, boots, gloves, balaclava and technical underwear, with lockers, showers and towels waiting for afterwards. A personal instructor greets the group, runs the safety briefing and leads 30 minutes of pitbike training before you take on four rides on the track for real. There is a beer or Red Bull each when the engines cool, and a Trivlu guide oversees the day. It is a genuine adrenaline hit with real machinery and real technique — lap by lap the confidence builds, the lines get braver, and one member of the group inevitably discovers a talent nobody asked for.',
        150.00, NULL, 60,
        'https://img.trivlu.com/498a8d98-cd9f-469f-9b38-6f04c551d542.avif',
        'Trivlu Guide; Private Transport (Roundtrip); Meet and greet with personal instructor; 30 min. Gearing up; Integral helmet each; Technical underwear each; Leather motorbike overall each; Balaclava each; Towel each; Lockers and showers with towels and amenities; 5 min. Safety briefing; Pitbike each; 30 min. Pitbike training; 4 Rides on Pitbike track; Beer or Redbull each; Qualified Instructor; Leather motorbike boots each; Leather motorbike gloves each',
        TRUE, '{"de":{"name":"Pitbike-Rennen","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Meet and Greet mit persönlichem Instruktor; 30 Min. Ausrüsten; Integralhelm pro Person; Funktionsunterwäsche pro Person; Leder-Motorradkombi pro Person; Sturmhaube pro Person; Handtuch pro Person; Schließfächer und Duschen mit Handtüchern und Pflegeprodukten; 5 Min. Sicherheitseinweisung; Pitbike pro Person; 30 Min. Pitbike-Training; 4 Fahrten auf der Pitbike-Strecke; Bier oder Red Bull pro Person; Qualifizierter Instruktor; Leder-Motorradstiefel pro Person; Leder-Motorradhandschuhe pro Person","description":"Echter Motorsport, auf JGA-Größe geschrumpft. Pitbike-Rennen bringt deine Gruppe auf eine eigens gebaute Offroad-Strecke bei Prag — privater Hin- und Rücktransport inklusive — und rüstet jeden Fahrer von Kopf bis Fuß aus: Integralhelm, Lederkombi, Stiefel, Handschuhe, Sturmhaube und Funktionsunterwäsche, mit Schließfächern, Duschen und Handtüchern für danach. Ein persönlicher Instruktor begrüßt die Gruppe, macht die Sicherheitseinweisung und leitet 30 Minuten Pitbike-Training, bevor du vier Fahrten auf der Strecke ernsthaft angehst. Wenn die Motoren abkühlen, gibt es ein Bier oder Red Bull pro Person, und ein Trivlu-Guide überwacht den Tag. Ein echter Adrenalinkick mit echten Maschinen und echter Technik — Runde für Runde wächst das Selbstvertrauen, die Linien werden mutiger, und einer aus der Gruppe entdeckt unweigerlich ein Talent, nach dem niemand gefragt hat."}}', CURRENT_TIMESTAMP),
       ('346a2db3-b01e-4376-b4a9-2930bee8e084', 'private-game-room-session', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Private Game Room Session',
        'Two hours, one private game lounge, zero people telling you to keep it down. The Private Game Room Session gives your group its own space stocked with a PlayStation 5, a VR system and a Nintendo console, plus a burger each and three Czech beers per player to keep the tournament fuelled. A Trivlu guide books it all and gets the group settled. From there it writes itself: bracketed multiplayer showdowns, VR humiliation for the volunteers, and the eternal truth that whoever talks the most wins the least. It is a brilliant low-effort slot for a stag itinerary — air-conditioned, competitive and sociable — ideal between daytime activities and a big night, or as recovery programming the morning after. Burgers, beers, controllers: the stag weekend''s most reliable two hours.',
        43.00, NULL, 120,
        'https://img.trivlu.com/80ccf351-1b5a-43cd-b20f-08c1d6e3d38f.jpg',
        'Trivlu Guide; 2 hrs. Private game room reservation; Burger each; 3 Beer each; Playstation 5 with VR system; Nintendo DS',
        TRUE, '{"de":{"name":"Private Session in Gaming-Room","includes":"Trivlu-Guide; 2 Std. private Gaming-Room-Reservierung; Burger pro Person; 3 Bier pro Person; PlayStation 5 mit VR-System; Nintendo DS","description":"Zwei Stunden, eine private Gaming-Lounge, niemand, der dir sagt, du sollst leiser sein. Die private Gaming-Room-Session gibt deiner Gruppe einen eigenen Raum mit PlayStation 5, VR-System und Nintendo-Konsole, dazu einen Burger pro Person und drei tschechische Biere pro Spieler, damit das Turnier Treibstoff hat. Ein Trivlu-Guide bucht alles und bringt die Gruppe unter. Von da an schreibt es sich von selbst: Multiplayer-Showdowns im Turnierbaum, VR-Demütigung für die Freiwilligen und die ewige Wahrheit, dass derjenige, der am meisten redet, am wenigsten gewinnt. Ein brillanter Low-Effort-Slot für ein JGA-Programm — klimatisiert, kompetitiv und gesellig — ideal zwischen Tagesaktivitäten und einer großen Nacht oder als Erholungsprogramm am Morgen danach. Burger, Bier, Controller: die verlässlichsten zwei Stunden des JGA-Wochenendes."}}', CURRENT_TIMESTAMP),
       ('46bf0b47-3bbf-40a4-935c-2acf2225e1f2', 'private-hotel-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Private Hotel Show',
        'The entertainment comes to you. The Private Hotel Show delivers a 15-minute professional performance directly to your hotel room — no venue, no queue, no leaving the sofa. It is the most flexible booking in the category: order additional performers for a bigger group show, time it as a surprise for the stag, or slot it between dinner and the club as a private warm-up act. A Trivlu guide handles the arrangements discreetly. The appeal is exactly its convenience and privacy: your room, your schedule, your group only. Fifteen minutes later the night has officially started, the stag''s composure has officially ended, and the group has a story that never needed anyone to find a taxi.',
        20.00, 120.00, 15,
        'https://img.trivlu.com/036ff6c6-3040-4ca9-b12c-fdbd01e2000d.jpg',
        'Trivlu Guide; 15 min. Strip Show',
        TRUE, '{"de":{"name":"Private Hotel-Show","includes":"Trivlu-Guide; 15 Min. Stripshow","description":"Die Unterhaltung kommt zu dir. Die private Hotel-Show liefert eine 15-minütige professionelle Performance direkt in dein Hotelzimmer — keine Location, keine Schlange, kein Aufstehen vom Sofa. Die flexibelste Buchung der Kategorie: Bestell zusätzliche Performerinnen für eine größere Gruppenshow, time sie als Überraschung für den Bräutigam oder schieb sie als privaten Warm-up-Act zwischen Dinner und Club. Ein Trivlu-Guide kümmert sich diskret um die Organisation. Der Reiz liegt genau in Bequemlichkeit und Privatsphäre: dein Zimmer, dein Zeitplan, nur deine Gruppe. Fünfzehn Minuten später hat die Nacht offiziell begonnen, die Fassung des Bräutigams ist offiziell dahin, und die Gruppe hat eine Geschichte, für die niemand ein Taxi finden musste."}}', CURRENT_TIMESTAMP),
       ('5814b0d8-8d0d-47e6-b75d-91f9b12384bf', 'quad-bikes', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Quad Bikes',
        'Mud, ditches, obstacles and a former military terrain to throw them all at you — quad biking outside Prague is short, intense and gloriously dirty. Each rider gets a 15-minute high-intensity run on the guided course, with a qualified instructor in charge and full equipment and safety gear provided. Private roundtrip transport is included and a Trivlu guide runs the day, so the group just shows up and rides. Fifteen minutes sounds brief until you have wrestled a quad through rutted army ground; it is exactly enough to leave arms aching and grins fixed. The format also makes it a smart post-party pick — a sharp burst of adrenaline that wakes the group up rather than wearing it out. Expect splattered clothing, disputed bragging rights and immediate demands for a rematch.',
        78.00, NULL, 60,
        'https://img.trivlu.com/63d9882b-22ca-446f-bb26-3069cdfa1e27.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); Qualified Instructor; Equipment & Safety Gear; 15 min. Quad Bike Ride each',
        TRUE, '{"de":{"name":"Quad-Fahrt","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Qualifizierter Instruktor; Ausrüstung & Schutzausrüstung; 15 Min. Quad-Fahrt pro Person","description":"Schlamm, Gräben, Hindernisse und ein ehemaliges Militärgelände, das dir alles davon um die Ohren haut — Quad fahren vor Prag ist kurz, intensiv und herrlich dreckig. Jeder Fahrer bekommt eine 15-minütige Highspeed-Runde auf dem geführten Parcours, mit qualifiziertem Instruktor und kompletter Ausrüstung und Schutzausrüstung. Privater Hin- und Rücktransport ist inklusive und ein Trivlu-Guide leitet den Tag, die Gruppe kommt also einfach und fährt. Fünfzehn Minuten klingen kurz, bis man ein Quad durch zerfurchten Armeeboden gewuchtet hat; es reicht genau, um Arme schmerzen und Grinsen festfrieren zu lassen. Das Format macht es auch zu einer cleveren Wahl nach der Party — ein kurzer Adrenalinstoß, der die Gruppe aufweckt, statt sie zu erschöpfen. Rechne mit verspritzter Kleidung, umstrittenen Angeberrechten und sofortigen Forderungen nach Revanche."}}', CURRENT_TIMESTAMP),
       ('06a5b1b1-7ce2-4a87-9249-5fd2e00888eb', 'rafting-extreme', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Rafting Extreme',
        'White water, thirty minutes from the city. Rafting Extreme takes your group to Veltrusy for two hours on the rapids — three to five guided runs, depending on how the river and the crew are feeling — with a qualified instructor in the boat and full equipment and safety gear provided. It is genuinely beginner-friendly: the briefing covers everything, the guided format keeps it safe, and the adrenaline arrives regardless of experience. Private roundtrip transport is included, there is a beer or soft drink for each paddler afterwards, and a Trivlu guide manages the whole excursion. Rafting is one of the best team activities a stag weekend can book — one boat, no room for passengers — and every capsize-adjacent moment becomes group legend by dinner. Allow around three hours door to door.',
        109.00, NULL, 180,
        'https://img.trivlu.com/15d22f9b-646a-46d0-b62a-3f6d271276d8.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); Equipment & Safety Gear; Qualified Instructor; Beer(s) or Soft Drink(s) each; 2 hrs. Rafting',
        TRUE, '{"de":{"name":"Rafting Extreme","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Ausrüstung & Schutzausrüstung; Qualifizierter Instruktor; Bier oder Softdrink pro Person; 2 Std. Rafting","description":"Wildwasser, dreißig Minuten von der Stadt. Rafting Extreme bringt deine Gruppe nach Veltrusy für zwei Stunden in den Stromschnellen — drei bis fünf geführte Abfahrten, je nachdem, wie Fluss und Crew drauf sind — mit qualifiziertem Instruktor im Boot und kompletter Ausrüstung und Schutzausrüstung. Wirklich anfängerfreundlich: Die Einweisung deckt alles ab, das geführte Format hält es sicher, und das Adrenalin kommt unabhängig von der Erfahrung. Privater Hin- und Rücktransport ist inklusive, danach gibt es ein Bier oder einen Softdrink für jeden Paddler, und ein Trivlu-Guide managt den gesamten Ausflug. Rafting ist eine der besten Teamaktivitäten, die ein JGA-Wochenende buchen kann — ein Boot, kein Platz für Passagiere — und jeder Beinahe-Kenterer wird bis zum Abendessen zur Gruppenlegende. Plane rund drei Stunden von Tür zu Tür ein."}}', CURRENT_TIMESTAMP),
       ('1d6b1ffb-f8f8-4365-ad9c-8b271b16b63d', 'river-boat-cruise', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'River Boat Cruise',
        'See Prague the way it photographs best — from the Vltava. This one-hour sightseeing cruise carries your group past Charles Bridge, Prague Castle and the Old Town, with audio guide or live commentary filling in the stories behind the skyline and a choice of indoor or open-deck seating whatever the weather does. Drinks are available on board, the atmosphere leans party as much as postcard, and a Trivlu guide gets everyone aboard without a hitch. For a stag weekend it is the perfect tempo-changer: an hour of easy scenery and cold drinks that still counts as culture, slotting neatly between a heavy lunch and an ambitious evening. The city drifts past, the group resets, and everyone gets the one classy photo their relatives will actually ask about.',
        37.00, 290.00, 60,
        'https://img.trivlu.com/613cdcc2-18d6-4d98-8e46-0cf64bd26253.webp',
        'Trivlu Guide; River Boat Cruise in Prague; 1-hour sightseeing cruise on the Vltava River; Views of Charles Bridge; Prague Castle and Old Town; Audio guide or live commentary; Indoor or open deck seating',
        TRUE, '{"de":{"name":"Bootsfahrt auf der Moldau","includes":"Trivlu-Guide; Bootsfahrt in Prag; 1-stündige Sightseeing-Fahrt auf der Moldau; Blick auf Karlsbrücke, Prager Burg und Altstadt; Audioguide oder Live-Kommentar; Innen- oder Freideckplätze","description":"Sieh Prag so, wie es sich am besten fotografiert — von der Moldau aus. Diese einstündige Sightseeing-Fahrt trägt deine Gruppe an der Karlsbrücke, der Prager Burg und der Altstadt vorbei, mit Audioguide oder Live-Kommentar zu den Geschichten hinter der Skyline und der Wahl zwischen Innen- oder Freideckplätzen, egal, was das Wetter macht. Getränke gibt es an Bord, die Stimmung ist genauso Party wie Postkarte, und ein Trivlu-Guide bringt alle ohne Probleme an Bord. Für ein JGA-Wochenende der perfekte Tempowechsel: eine Stunde entspannte Kulisse und kalte Drinks, die trotzdem als Kultur zählt und sauber zwischen ein schweres Mittagessen und einen ambitionierten Abend passt. Die Stadt zieht vorbei, die Gruppe resettet, und jeder bekommt das eine seriöse Foto, nach dem die Verwandten tatsächlich fragen."}}', CURRENT_TIMESTAMP),
       ('ab42d52b-429e-4ecf-bd2e-92c6908ec9c6', 'stag-challenge', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Self Tapping Pub',
        'Fourteen taps, one card, no waiting at the bar. The Self-Tapping Pub reserves your group seating in one of Prague''s most dangerous concepts: a bar where each of you gets a tapping card preloaded with 500 CZK and pours your own beer from a wall of fourteen self-serve taps. Craft styles, Czech classics, small tasting pours or full glasses — the card tracks it, you pour it, the group argues about which tap wins. A Trivlu guide books everything and explains the system before letting you loose. It is an interactive, sociable format that turns drinking into a tasting tournament, and the self-serve wall removes the single greatest enemy of a stag group: the queue. Relaxed enough to talk, novel enough to remember, Czech enough to matter.',
        40.00, NULL, 120,
        'https://img.trivlu.com/ddce1cbf-44ec-4267-9dbf-313bf82f184c.png',
        'Trivlu Guide; Table reservation; Tapping card each; Prepaid tapping of 500 Czk each; 14 taps with beer to choose from',
        TRUE, '{"de":{"name":"Selbstzapf-Kneipe","includes":"Trivlu-Guide; Tischreservierung; Zapfkarte pro Person; Vorausbezahltes Zapfguthaben 500 CZK pro Person; 14 Zapfhähne mit Bier zur Auswahl","description":"Vierzehn Zapfhähne, eine Karte, kein Warten an der Bar. Die Selbstzapf-Kneipe reserviert deiner Gruppe Plätze in einem der gefährlichsten Konzepte Prags: einer Bar, in der jeder eine Zapfkarte mit 500 CZK Guthaben bekommt und sein Bier selbst an einer Wand mit vierzehn Selbstzapfhähnen zapft. Craft-Sorten, tschechische Klassiker, kleine Probierschlucke oder volle Gläser — die Karte zählt mit, du zapfst, die Gruppe streitet, welcher Hahn gewinnt. Ein Trivlu-Guide bucht alles und erklärt das System, bevor er die Gruppe loslässt. Ein interaktives, geselliges Format, das Trinken in ein Verkostungsturnier verwandelt, und die Selbstzapf-Wand beseitigt den größten Feind jeder JGA-Gruppe: die Schlange. Entspannt genug zum Reden, neu genug zum Erinnern, tschechisch genug, um zu zählen."}}', CURRENT_TIMESTAMP),
       ('a5e96eac-5696-4bfc-af3e-7a7d9ca84e08', 'sight-beering', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Sight Beering',
        'Sightseeing, corrected. Sight Beering swaps museums for a guided bar-hopping route through the heart of Prague, stopping at three to four local pubs and bars over three hours, with a full hour of unlimited beer built in along the way. Your Trivlu guide knows which rooms have the atmosphere, which taps are worth the detour and which stories about the city are actually true, so the group gets the best of Prague''s pub culture without a single wrong turn. It is the ideal first-evening activity: you learn the lay of the land, find the venues worth returning to, and bond the group over pints rather than itineraries. By the final stop you will have seen more of the real city than most tour buses manage — and remembered at least half of it.',
        31.00, NULL, 180,
        'https://img.trivlu.com/b060b678-c76e-4d3b-9a5a-d447f7547798.webp',
        'Trivlu Guide; Guided Bar-Hopping Route in Prague; Visit 3-4 Local Pubs or Bars; hour of Unlimited beer',
        TRUE, '{"de":{"name":"Sight-Beering","includes":"Trivlu-Guide; Geführte Bar-Hopping-Route in Prag; Besuch von 3–4 lokalen Kneipen oder Bars; Eine Stunde unbegrenzt Bier","description":"Sightseeing, korrigiert. Sight-Beering tauscht Museen gegen eine geführte Bar-Hopping-Route durch das Herz Prags, mit Stopps in drei bis vier lokalen Kneipen und Bars über drei Stunden und einer vollen Stunde unbegrenzt Bier unterwegs. Dein Trivlu-Guide weiß, welche Läden Atmosphäre haben, welche Zapfhähne den Umweg wert sind und welche Geschichten über die Stadt tatsächlich stimmen — so bekommt die Gruppe das Beste aus Prags Kneipenkultur ohne einen einzigen falschen Abzweig. Die ideale Aktivität für den ersten Abend: Du lernst die Gegend kennen, findest die Locations, zu denen sich die Rückkehr lohnt, und schweißt die Gruppe bei Bier statt über Zeitplänen zusammen. Beim letzten Stopp hast du mehr von der echten Stadt gesehen als die meisten Tourbusse — und dich an mindestens die Hälfte erinnert."}}', CURRENT_TIMESTAMP),
       ('9e7aa677-026d-4d3e-8e28-3b2180a81aef', 'slivovice-tour-and-tasting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Slivovice Tour & Tasting',
        'Czech plum brandy taken seriously — then not so seriously. This experience begins with a 55-minute guided tour of a slivovice museum, followed by a curated tasting of three traditional Czech slivovice pours per person. The food alone justifies the booking: canapés, Wallachian kyselice sour soup, roasted BBQ ribs, bread and plum sweet dumplings with poppy seed, plus a bottle of beer each. And because this is a stag weekend, the sitting rounds off with a 15-minute show performance nobody saw coming. A Trivlu guide manages the full three-and-a-half-hour arc. It is the rare booking that genuinely covers culture, cuisine and comedy in one afternoon — you leave knowing more about the national spirit than most Czechs, fed like royalty and laughing like idiots.',
        109.00, NULL, 210,
        'https://img.trivlu.com/5efc6406-c500-4de3-afcb-784de93cc9b6.jpeg',
        'Trivlu Guide; 55 min. Slivovice museum tour; 3 glasses Slivovice for degustation each; 3 Canapes each; Wallachia kyselice (sour soup) each; Roasted BBQ ribs each; Bread; Plum sweet dumplings with poppy each; bottle 0; 3l beer per pax; 15 minutes Strip Show',
        TRUE, '{"de":{"name":"Slivovice-Tour & Verkostung","includes":"Trivlu-Guide; 55 Min. Slivovice-Museumstour; 3 Gläser Slivovice zur Verkostung pro Person; 3 Canapés pro Person; Walachische Kyselice (Sauersuppe) pro Person; Geröstete BBQ-Rippchen pro Person; Brot; Süße Pflaumenknödel mit Mohn pro Person; Flasche 0,3 l Bier pro Person; 15 Minuten Stripshow","description":"Tschechischer Pflaumenbrand, ernst genommen — und dann nicht mehr so ernst. Dieses Erlebnis beginnt mit einer 55-minütigen geführten Tour durch ein Slivovice-Museum, gefolgt von einer kuratierten Verkostung von drei traditionellen tschechischen Slivovice-Proben pro Person. Allein das Essen rechtfertigt die Buchung: Canapés, walachische Kyselice-Sauersuppe, geröstete BBQ-Rippchen, Brot und süße Pflaumenknödel mit Mohn, dazu eine Flasche Bier pro Person. Und weil es ein JGA-Wochenende ist, endet der Termin mit einer 15-minütigen Show, die niemand kommen sah. Ein Trivlu-Guide managt den gesamten dreieinhalbstündigen Bogen. Die seltene Buchung, die wirklich Kultur, Küche und Comedy an einem Nachmittag abdeckt — die Gruppe geht mit mehr Wissen über den Nationalschnaps als die meisten Tschechen, gesättigt wie Könige und lachend wie Idioten."}}', CURRENT_TIMESTAMP),
       ('28ec3fe3-5cce-4d23-859c-dc6a170e80ed', 'stag-arrest', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Stag Arrest',
        'The stag has it coming, and Prague is the place to serve the warrant. Stag Arrest is a fully staged prank in which actors posing as police interrupt the evening and arrest the groom in front of the group — a planned, comedic setup that builds to a big reveal, followed by a 15-minute show and a bottle of bubbly at your reserved table to toast his ordeal. A fake policeman commits to the role, a Trivlu guide choreographs the timing, and the rest of the group''s only job is to keep straight faces and cameras rolling. Thirty minutes, one panicking groom, footage for a lifetime. It is the classic stag stitch-up executed properly — safe, scripted and merciless — and the retelling at the wedding is practically guaranteed.',
        39.00, 280.00, 30,
        'https://img.trivlu.com/83ff61a4-4735-46c1-bcf5-9e6df1872cf1.png',
        'Trivlu Guide; Table reservation; Bottle of bubbly; Fake Policeman; Stag Arrest Prank; 15 minutes Strip Show',
        TRUE, '{"de":{"name":"Verhaftung des Bräutigams","includes":"Trivlu-Guide; Tischreservierung; Flasche Sekt; Falscher Polizist; Verhaftungs-Prank; 15 Minuten Stripshow","description":"Der Bräutigam hat es verdient, und Prag ist der richtige Ort, um den Haftbefehl zu vollstrecken. Die Verhaftung des Bräutigams ist ein komplett inszenierter Prank, bei dem Schauspieler als Polizisten den Abend unterbrechen und den Bräutigam vor der Gruppe verhaften — ein geplantes, komödiantisches Setup, das auf eine große Enthüllung zusteuert, gefolgt von einer 15-minütigen Show und einer Flasche Sekt an deinem reservierten Tisch, um auf seine Tortur anzustoßen. Ein falscher Polizist geht voll in seiner Rolle auf, ein Trivlu-Guide choreografiert das Timing, und die einzige Aufgabe der Gruppe ist es, ernst zu bleiben und die Kameras laufen zu lassen. Dreißig Minuten, ein panischer Bräutigam, Filmmaterial fürs Leben. Der klassische JGA-Streich, richtig ausgeführt — sicher, geskriptet und gnadenlos — und die Nacherzählung auf der Hochzeit ist praktisch garantiert."}}', CURRENT_TIMESTAMP),
       ('585f61b6-7edc-4e0d-9a7c-30695d8a8f1e', 'stag-challenge-2', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Stag Challenge',
        'The heavyweight title fight of Prague bar crawls. Stag Challenge runs your group through four bars over three hours with a Trivlu guide setting the pace: an hour of the Macháček drinking game, a bottle of Jägermeister on the table, burgers and fries to keep everyone upright, the wheel-of-shots game dealing three shots each, an hour of unlimited beer, wine and cocktails, an hour of the King of the Ring game, table football, and free entry into a night club to finish. Beers along the route are included too. It is a structured escalation — games first, chaos later — which is exactly what a proper stag night needs: momentum, forfeits, and a guide making sure the group reaches the club as one unit. Prague nightlife, taken by force.',
        123.00, NULL, 180,
        'https://img.trivlu.com/75c69a58-1311-434a-8f6d-0267130db24d.jpg',
        'Trivlu Guide; Local tips; Free entry to chosen clubs in Prague; hour of Game of Macháček; Table reservation; Bottle of Jägermeister; 1 of Soft Drinks; 2 Beer each; Burger each; French fries each; 3 shots to choose; wheel of shots game; 3 Shot each (chosen by wheel of shots); hour of Unlimited beer; wine; cocktails; hour of King of the ring game; Table football; Night Club Entry',
        TRUE, '{"de":{"name":"JGA-Herausforderung","includes":"Trivlu-Guide; Lokale Tipps; Freier Eintritt in ausgewählte Clubs in Prag; Eine Stunde Macháček-Spiel; Tischreservierung; Flasche Jägermeister; 1 Softdrink; 2 Bier pro Person; Burger pro Person; Pommes pro Person; 3 Shots zur Auswahl; Shot-Glücksrad; 3 Shots pro Person (vom Glücksrad bestimmt); Eine Stunde unbegrenzt Bier, Wein, Cocktails; Eine Stunde „King of the Ring“; Tischfußball; Nachtclub-Eintritt","description":"Der Schwergewichts-Titelkampf unter Prags Kneipentouren. Die Stag Challenge führt deine Gruppe in drei Stunden durch vier Bars, ein Trivlu-Guide gibt das Tempo vor: eine Stunde Macháček-Trinkspiel, eine Flasche Jägermeister auf dem Tisch, Burger und Pommes, damit alle aufrecht bleiben, das Shot-Glücksrad mit drei Shots pro Person, eine Stunde unbegrenzt Bier, Wein und Cocktails, eine Stunde „King of the Ring“, Tischfußball und zum Abschluss freier Eintritt in einen Nachtclub. Biere entlang der Route sind ebenfalls inklusive. Eine strukturierte Eskalation — erst Spiele, dann Chaos — genau das, was eine richtige JGA-Nacht braucht: Schwung, Strafen und einen Guide, der dafür sorgt, dass die Gruppe geschlossen im Club ankommt. Prags Nachtleben, im Sturm genommen."}}', CURRENT_TIMESTAMP),
       ('eeacefd5-86da-4261-a8dc-cbe1173d7942', 'stag-nappy-change', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Stag Nappy Change',
        'Somewhere between a roast and a rite of passage sits the Nappy Change. In this 30-minute club-setting prank, the stag is dressed in a diaper and treated to a humorous adult roleplay performance in front of the entire group, complete with a 15-minute show and drinks included while his dignity is formally retired. A Trivlu guide arranges the setup so the surprise lands perfectly. It is deliberately over the top: light-hearted, loud and mortifying in exactly the way stag traditions demand, with the group''s phones capturing every stage of the groom''s acceptance journey. If the stag has spent years dishing it out, this is the evening the balance is restored. Book it, keep the secret, and let the nappy do the rest.',
        46.00, 335.00, 30,
        'https://img.trivlu.com/1b7c1d0d-f392-4347-bf89-47c969f6d5c6.PNG',
        'Trivlu Guide; 15 min. Strip Show; Drink(s) each; Nappy change',
        TRUE, '{"de":{"name":"Windelwechsel für den Bräutigam","includes":"Trivlu-Guide; 15 Min. Stripshow; Drink pro Person; Windelwechsel","description":"Irgendwo zwischen Roast und Initiationsritus liegt der Windelwechsel. Bei diesem 30-minütigen Prank im Club wird der Bräutigam in eine Windel gesteckt und vor der gesamten Gruppe mit einer humorvollen Erwachsenen-Rollenspiel-Performance bedacht, komplett mit 15-minütiger Show und Drinks inklusive, während seine Würde offiziell in den Ruhestand geht. Ein Trivlu-Guide organisiert das Setup, damit die Überraschung perfekt sitzt. Bewusst übertrieben: leichtfüßig, laut und peinlich genau so, wie JGA-Traditionen es verlangen, während die Handys der Gruppe jede Phase der Akzeptanzreise des Bräutigams festhalten. Hat der Bräutigam jahrelang ausgeteilt, ist dies der Abend, an dem die Bilanz ausgeglichen wird. Buchen, Geheimnis bewahren und die Windel den Rest erledigen lassen."}}', CURRENT_TIMESTAMP),
       ('e2994ece-9ab7-4d1f-ba98-ea7dae5515b8', 'stag-ring-challenge', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Stag Ring Challenge',
        'The stag talks a big game; the ring finds out. The Stag Ring Challenge is a supervised combat-sports experience where the groom steps into the ring with a professional female fighter for a controlled sparring session — full boxing kit provided, from gloves and shorts to mouthguard, shin guards and helmet. A qualified instructor runs the safety briefing, a referee controls every round, and private roundtrip transport is included, with a Trivlu guide overseeing the day. The control is the point: it is adrenaline with rules, not recklessness — and the sight of the stag discovering exactly how much technique matters is worth the booking alone. Two hours door to door, one humbled groom, and a group that will referee the retelling for years.',
        40.00, 382.00, 120,
        'https://img.trivlu.com/74ac01a2-871f-410d-aed6-1d6fc96cccaf.jpg',
        'Trivlu Guide; Private Transport (Roundtrip); Qualified Instructor; Referee; Boxing equipment for the Stag (boxing gloves; boxing shorts; mouthguard; shin-guard; boxing helmet); Professional girl fighter; Safety briefing',
        TRUE, '{"de":{"name":"Ring-Herausforderung für den Bräutigam","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Qualifizierter Instruktor; Ringrichter; Boxausrüstung für den Bräutigam (Boxhandschuhe, Boxshorts, Mundschutz, Schienbeinschoner, Boxhelm); Professionelle Kämpferin; Sicherheitseinweisung","description":"Der Bräutigam hat eine große Klappe; der Ring findet es heraus. Die Ring-Challenge ist ein beaufsichtigtes Kampfsport-Erlebnis, bei dem der Bräutigam für ein kontrolliertes Sparring mit einer professionellen Kämpferin in den Ring steigt — komplette Boxausrüstung inklusive, von Handschuhen und Shorts bis Mundschutz, Schienbeinschonern und Helm. Ein qualifizierter Instruktor macht die Sicherheitseinweisung, ein Ringrichter kontrolliert jede Runde, privater Hin- und Rücktransport ist inklusive, und ein Trivlu-Guide überwacht den Tag. Die Kontrolle ist der Punkt: Adrenalin mit Regeln, nicht Leichtsinn — und der Anblick des Bräutigams, der entdeckt, wie viel Technik zählt, ist die Buchung allein wert. Zwei Stunden von Tür zu Tür, ein demütiger Bräutigam und eine Gruppe, die die Nacherzählung noch Jahre lang schiedsrichtert."}}', CURRENT_TIMESTAMP),
       ('4420dfd4-60bb-4f9e-ba08-535a0d2e4945', 'steak-and-private-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Steak & Private Show',
        'Steak first, spectacle second. This 100-minute evening seats your group in a private restaurant setting in central Prague for a proper steak with fries, sauce and two beers each — a dinner that takes itself seriously. Then the room changes gear: a private 15-minute show performance for your group, with a spotlight moment reserved for one selected guest, and everybody knows which one. A Trivlu guide books the room and runs the timing. It is the format that makes stag dinners work: good food with no compromises, entertainment with no travel between venues, and a private setting where the group can be exactly as loud as the occasion demands. Solid, simple and reliably the evening''s first highlight.',
        47.00, NULL, 100,
        'https://img.trivlu.com/e58ff74a-ee07-419c-99e6-9a2b15f33dc7.png',
        'Trivlu Guide; Steak each; French fries each; Sauce each; 2 Beer per person; 15 minutes Strip Show',
        TRUE, '{"de":{"name":"Steak & Private Show","includes":"Trivlu-Guide; Steak pro Person; Pommes pro Person; Sauce pro Person; 2 Bier pro Person; 15 Minuten Stripshow","description":"Erst Steak, dann Spektakel. Dieser 100-minütige Abend setzt deine Gruppe in einem privaten Restaurantbereich im Zentrum Prags an den Tisch — für ein richtiges Steak mit Pommes, Sauce und zwei Bier pro Person — ein Dinner, das sich ernst nimmt. Dann schaltet der Raum einen Gang hoch: eine private 15-minütige Show für deine Gruppe, mit einem Spotlight-Moment für einen ausgewählten Gast, und alle wissen, welchen. Ein Trivlu-Guide bucht den Raum und hält das Timing. Das Format, das JGA-Dinner funktionieren lässt: gutes Essen ohne Kompromisse, Unterhaltung ohne Location-Wechsel und ein privater Rahmen, in dem die Gruppe genau so laut sein kann, wie der Anlass es verlangt. Solide, einfach und verlässlich das erste Highlight des Abends."}}', CURRENT_TIMESTAMP),
       ('4d13c66c-71ed-4d36-acb2-21657008f424', 'succulent-bbq-ribs', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Succulent BBQ Ribs',
        'Half a kilo of ribs each, and no judgement. This dinner books your group a reserved table for a proper barbecue feast: 500 grams of succulent ribs per person, french fries on the side and two beers each, served in a relaxed restaurant setting made for long, loud tables. A Trivlu guide gets the group in and settled. Allow a generous couple of hours — good ribs deserve commitment, and this is finger food at its most serious. As stag do dinners go it is a reliable crowd-pleaser: no menu debates, no tiny portions, just meat, beer and a table getting steadily messier and happier. It is the ideal fuel stop before a big Prague night out — heavy enough to build a foundation, casual enough that nobody has to behave.',
        43.00, NULL, 107,
        'https://img.trivlu.com/14cf0df2-de9b-41c7-aeee-85532b54bbdd.jpg',
        'Trivlu Guide; Table reservation; 500 g of Ribs each; French fries each; 2 Beer each',
        TRUE, '{"de":{"name":"Saftige BBQ-Rippchen","includes":"Trivlu-Guide; Tischreservierung; 500 g Rippchen pro Person; Pommes pro Person; 2 Bier pro Person","description":"Ein halbes Kilo Rippchen pro Person, und niemand urteilt. Dieses Dinner bucht deiner Gruppe einen reservierten Tisch für ein richtiges Barbecue-Festmahl: 500 Gramm saftige Rippchen pro Person, Pommes dazu und zwei Bier pro Kopf, serviert in einem entspannten Restaurant, das für lange, laute Tische gemacht ist. Ein Trivlu-Guide bringt die Gruppe rein und unter. Plane großzügig ein paar Stunden ein — gute Rippchen verdienen Hingabe, und das ist Fingerfood in seiner ernstesten Form. Unter den JGA-Dinnern ein verlässlicher Publikumsliebling: keine Menü-Debatten, keine winzigen Portionen, nur Fleisch, Bier und ein Tisch, der stetig schmutziger und fröhlicher wird. Der ideale Tankstopp vor einer großen Prager Nacht — schwer genug für eine Grundlage, locker genug, dass sich niemand benehmen muss."}}', CURRENT_TIMESTAMP),
       ('4ebc7d55-24c7-481d-98b4-cd1afe4ee2ec', 'swimming-beer-bike', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Swimming beer bike',
        'The beer bike, but floating. Prague''s swimming beer bike puts your group on the water for 90 minutes with unlimited beer, a captain in charge of the important directional decisions, and the city sliding past as you pedal, pour and generally fail to help. A Trivlu guide gets everyone aboard and the taps flowing. It is the rare activity that combines sightseeing, drinking and mild exercise in proportions a stag group can actually endorse — the pedalling is optional in spirit, the beer is not. The novelty alone makes it a highlight: plenty of cities have bar crawls, very few let you captain one down a river. Expect singing, expect splashing, expect the group photo of the weekend. Ninety minutes on the water, zero designated drivers required.',
        52.00, 410.00, 90,
        'https://img.trivlu.com/bac6c3d7-8be1-4cc6-95ad-1798c3e18d68.avif',
        'Trivlu Guide; River Boat Cruise; Captain; Unlimited beer',
        TRUE, '{"de":{"name":"Schwimmendes Beer-Bike","includes":"Trivlu-Guide; Bootsfahrt; Kapitän; Unbegrenzt Bier","description":"Das Beer Bike, nur schwimmend. Prags schwimmendes Beer Bike setzt deine Gruppe für 90 Minuten aufs Wasser — mit unbegrenzt Bier, einem Kapitän, der die wichtigen Richtungsentscheidungen trifft, und der Stadt, die vorbeizieht, während du trittst, einschenkst und generell nicht viel hilfst. Ein Trivlu-Guide bringt alle an Bord und die Zapfhähne zum Laufen. Die seltene Aktivität, die Sightseeing, Trinken und leichte Bewegung in Proportionen kombiniert, die eine JGA-Gruppe tatsächlich gutheißen kann — das Treten ist im Geiste optional, das Bier nicht. Allein die Neuheit macht es zum Highlight: Viele Städte haben Kneipentouren, sehr wenige lassen dich eine davon den Fluss hinunter steuern. Rechne mit Gesang, rechne mit Spritzern, rechne mit dem Gruppenfoto des Wochenendes. Neunzig Minuten auf dem Wasser, null Fahrer nötig."}}', CURRENT_TIMESTAMP),
       ('4a9ea67d-2729-42dc-9393-0baf53be0f2a', 'tiki-boat', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Tiki Boat',
        'A tropical bar, inexplicably sailing through central Europe. The Tiki Boat gives your group a 90-minute cruise through Prague with unlimited beer flowing the entire time, a captain handling the navigation, and iconic views of Charles Bridge and Prague Castle drifting past the deck. A Trivlu guide gets everyone aboard. The contrast is the whole charm: tiki-bar atmosphere, Czech riverbanks, and a skyline that has absolutely no idea what to make of you. It is one of the most effortless wins on a stag itinerary — no skill, no schedule, just 90 minutes of cold beer, warm vibes and the best photo backdrop in the city. Board thirsty, disembark delighted, and argue afterwards about whether the castle or the third round was the highlight.',
        65.00, 450.00, 90,
        'https://img.trivlu.com/d990b187-9c74-4ba6-94c1-193250fde0ac.jpg',
        'Trivlu Guide; 90 min. River Boat Cruise; 90 min. Unlimited beer; Captain',
        TRUE, '{"de":{"name":"Tiki-Boot","includes":"Trivlu-Guide; 90 Min. Bootsfahrt; 90 Min. unbegrenzt Bier; Kapitän","description":"Eine Tropenbar, die unerklärlicherweise durch Mitteleuropa schippert. Das Tiki-Boot gibt deiner Gruppe eine 90-minütige Fahrt durch Prag mit unbegrenzt Bier die ganze Zeit, einem Kapitän, der die Navigation übernimmt, und ikonischen Blicken auf Karlsbrücke und Prager Burg, die am Deck vorbeiziehen. Ein Trivlu-Guide bringt alle an Bord. Der Kontrast ist der ganze Charme: Tiki-Bar-Atmosphäre, tschechische Flussufer und eine Skyline, die absolut nicht weiß, was sie von deiner Gruppe halten soll. Einer der mühelosesten Siege in einem JGA-Programm — kein Können, kein Zeitplan, nur 90 Minuten kaltes Bier, warme Vibes und die beste Fotokulisse der Stadt. Durstig an Bord, begeistert von Bord, und danach streiten, ob die Burg oder die dritte Runde das Highlight war."}}', CURRENT_TIMESTAMP),
       ('f9eebc99-9c0b-4ef8-bb6d-6bb9bd380aaa', 'unlimited-paintball-experience', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Unlimited rubber paintball experience',
        'No counting rounds, no rationing ammo — just unlimited rubber balls and a full hour to use them. The rubber paintball experience runs your group through fast, repeatable battles where the ammunition never runs out, which changes the game entirely: no one hides to save shots, every round is all-out, and the rematches keep coming until the hour is done. Rubber balls mean less mess than classic paint while keeping every bit of the adrenaline and the satisfying thwack of a direct hit. There is a beer or soft drink for each player afterwards, and a Trivlu guide manages the session start to finish. It is the format for groups who found normal paintball too polite — pure volume, pure chaos, and a very democratic distribution of bruised egos. Fire at will.',
        35.00, NULL, 180,
        'https://img.trivlu.com/db1b954e-cb38-4ea7-a507-1892cd2c9e3b.png',
        'Trivlu guide; 1 hour play; unlimited rubber balls; beer of softdrink each',
        TRUE, '{"de":{"name":"Unbegrenztes Gummiball-Paintball","includes":"Trivlu-Guide; 1 Stunde Spiel; Unbegrenzt Gummibälle; Bier oder Softdrink pro Person","description":"Kein Schusszählen, keine Munitionsrationierung — nur unbegrenzt Gummibälle und eine volle Stunde, um sie zu verbrauchen. Das Gummiball-Paintball-Erlebnis schickt deine Gruppe durch schnelle, wiederholbare Gefechte, bei denen die Munition nie ausgeht — und das verändert das Spiel komplett: Niemand versteckt sich, um Schüsse zu sparen, jede Runde ist volle Kraft voraus, und die Revanchen kommen, bis die Stunde um ist. Gummibälle bedeuten weniger Sauerei als klassische Farbe, mit dem ganzen Adrenalin und dem befriedigenden Klatschen eines Volltreffers. Danach gibt es ein Bier oder einen Softdrink für jeden Spieler, und ein Trivlu-Guide managt die Session von Anfang bis Ende. Das Format für Gruppen, denen normales Paintball zu höflich war — pure Masse, pures Chaos und eine sehr demokratische Verteilung angeknackster Egos. Feuer frei."}}', CURRENT_TIMESTAMP),
       ('6f3aaefe-27b2-4e96-84f3-5d3479b0a181', 'vip-cabaret-night-package', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'VIP Cabaret Night Package',
        'The all-in-one big night, assembled properly. The VIP Cabaret Night Package covers entry to one of Prague''s top adult venues with a reserved table, a 10-minute show performance, and — the centrepiece — the stag himself on stage for a 10-minute spotlight he will absolutely not choose for himself. The table gets a 0.7-litre bottle of spirits of your choosing, the stag drinks beer all night on the house, and he leaves with a commemorative T-shirt to prove it all happened. A Trivlu guide arranges entry, seating and timing across the three-hour evening. It is the closing-night format: no logistics, no queues, one venue, everything included — the group sits down together and the night simply happens around them.',
        93.00, 700.00, 180,
        'https://img.trivlu.com/f74e82f6-4e13-4c42-b51d-59c3f2989da3.jpg',
        'Trivlu Guide; Strip Club Entry; strip club table reservation; 10 min. Lesbian Show; 10 min. Stag show on the stage; bottle 0.7L of alcohol (for choosing); Unlimited Beer for Stag; T-shirt for the stag',
        TRUE, '{"de":{"name":"Cabaret-Nachtpaket (VIP)","includes":"Trivlu-Guide; Stripclub-Eintritt; Tischreservierung im Stripclub; 10 Min. Lesben-Show; 10 Min. Bräutigam-Show auf der Bühne; Flasche 0,7 l Spirituose (nach Wahl); Unbegrenzt Bier für den Bräutigam; T-Shirt für den Bräutigam","description":"Die große Nacht als All-in-one, richtig zusammengestellt. Das VIP-Cabaret-Nacht-Paket umfasst den Eintritt in eines der Top-Adult-Venues Prags mit reserviertem Tisch, eine 10-minütige Show und — das Herzstück — den Bräutigam selbst für 10 Minuten im Rampenlicht auf der Bühne, was er sich garantiert nicht selbst aussuchen würde. Der Tisch bekommt eine 0,7-Liter-Flasche Spirituosen deiner Wahl, der Bräutigam trinkt die ganze Nacht Bier aufs Haus und geht mit einem Erinnerungs-T-Shirt als Beweis, dass alles wirklich passiert ist. Ein Trivlu-Guide organisiert Eintritt, Plätze und Timing über den dreistündigen Abend. Das Format für die Abschlussnacht: keine Logistik, keine Schlangen, eine Location, alles inklusive — die Gruppe setzt sich zusammen hin, und die Nacht passiert einfach um sie herum."}}', CURRENT_TIMESTAMP),
       ('477e2450-6d0d-4454-9308-268afa12db58', 'vip-club-entrance', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'VIP Club Entrance',
        'Skip the queue, skip the compromise. VIP Club Entrance walks your group past the line and into one of Prague''s upscale clubs, where top DJs run mainly house — the kind of tracks that fill a dance floor and keep it full. Your table is reserved, bottle service is included, and a Trivlu guide handles the entry so the night begins at the door rather than in front of it. For a stag group it solves the classic end-of-night problem: ten people, one door policy, zero patience. With VIP entry the group arrives together, sits together and holds its own corner of the club all night. Dress sharp, pace the bottles, and let the DJ do the heavy lifting — this is the closing chapter of a Prague night done properly.',
        60.00, NULL, 180,
        'https://img.trivlu.com/0f8081cf-cd96-4eab-972c-79772ddf7792.jpeg',
        'Trivlu Guide; Table reservation; Bottle Service; Night Club VIP Entry',
        TRUE, '{"de":{"name":"VIP-Club-Eintritt","includes":"Trivlu-Guide; Tischreservierung; Flaschenservice; VIP-Eintritt Nachtclub","description":"Schlange überspringen, Kompromisse überspringen. Der VIP-Club-Eintritt führt deine Gruppe an der Schlange vorbei in einen der gehobenen Clubs Prags, wo Top-DJs hauptsächlich House auflegen — die Art Tracks, die eine Tanzfläche füllen und voll halten. Dein Tisch ist reserviert, Flaschenservice ist inklusive, und ein Trivlu-Guide regelt den Eintritt, damit die Nacht an der Tür beginnt statt davor. Für eine JGA-Gruppe löst es das klassische Problem am Ende der Nacht: zehn Leute, eine Türpolitik, null Geduld. Mit VIP-Eintritt kommt die Gruppe zusammen an, sitzt zusammen und hält die ganze Nacht ihre eigene Ecke im Club. Schick anziehen, die Flaschen einteilen und den DJ die Arbeit machen lassen — das Schlusskapitel einer Prager Nacht, richtig gemacht."}}', CURRENT_TIMESTAMP),
       ('56d630db-6817-43e9-a765-8e7d61ae6b15', 'vr-gaming', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'VR Gaming',
        'Two hours in Prague''s virtual reality playground, and the city centre location means it slots into any itinerary. Your group gets a full two hours of playing time on cutting-edge VR setups with a private chill-out zone to retreat to, plus two beers or soft drinks each for spectating between rounds — which is half the entertainment, because watching a grown man flail at invisible enemies never gets old. A Trivlu guide books it all in. VR is the sleeper hit of stag weekends: genuinely competitive, endlessly funny from the outside, and completely weatherproof. It works as an afternoon session, a hangover-friendly morning or a pre-dinner tournament, and it guarantees the group leaves with at least one video that will resurface at the wedding. Headsets on, dignity off.',
        29.00, NULL, 120,
        'https://img.trivlu.com/a80ea274-4cce-4151-ac8d-93f0cc0a7d04.webp',
        'Trivlu Guide; 2 hrs. Playing Time; 2 Beer(s) or Soft Drink(s) each',
        TRUE, '{"de":{"name":"VR-Gaming","includes":"Trivlu-Guide; 2 Std. Spielzeit; 2 Bier oder Softdrinks pro Person","description":"Zwei Stunden in Prags Virtual-Reality-Spielplatz, und dank der Lage im Stadtzentrum passt es in jedes Programm. Deine Gruppe bekommt zwei volle Stunden Spielzeit an modernsten VR-Setups mit privater Chill-out-Zone zum Zurückziehen, dazu zwei Bier oder Softdrinks pro Person fürs Zuschauen zwischen den Runden — was die halbe Unterhaltung ist, denn einem erwachsenen Mann beim Fuchteln gegen unsichtbare Feinde zuzusehen, wird nie alt. Ein Trivlu-Guide bucht alles. VR ist der Geheimtipp der JGA-Wochenenden: wirklich kompetitiv, von außen endlos lustig und komplett wetterfest. Es funktioniert als Nachmittags-Session, als katerfreundlicher Morgen oder als Turnier vor dem Dinner und garantiert, dass die Gruppe mit mindestens einem Video rausgeht, das auf der Hochzeit wieder auftaucht. Headsets auf, Würde ab."}}', CURRENT_TIMESTAMP),
       ('47e76c48-dc2c-473c-bc88-003fe67ae719', 'water-gun-battle', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Water gun battle',
        'Bring out the water guns and watch grown men take it far too seriously. The Water Gun Battle gives your group a full hour of fast-paced team combat — simple tactical play, constant soakings and the purest kind of competitive nonsense — with private transport included and a drink for each fighter when the ceasefire is called. A Trivlu guide organises the session so all you decide is teams and tactics. It is the lightest-hearted battle format on the Prague list: zero bruises, zero skill barrier and maximum comedy, especially once the alliances start collapsing. Perfect for warm weather and groups mixing fitness levels, it burns energy, cools everyone down and produces the kind of soaked, grinning group photo that sums up a stag weekend better than any nightclub shot.',
        40.00, NULL, 90,
        'https://img.trivlu.com/b360f19f-01a4-46d8-99c0-cbc4f857991c.jpg',
        'Trivlu guide; Private transport; 1 hour of play; Drink each',
        TRUE, '{"de":{"name":"Wasserpistolen-Schlacht","includes":"Trivlu-Guide; Privater Transport; 1 Stunde Spiel; Drink pro Person","description":"Hol die Wasserpistolen raus und sieh zu, wie erwachsene Männer es viel zu ernst nehmen. Die Wasserpistolen-Schlacht gibt deiner Gruppe eine volle Stunde rasanten Teamkampf — einfache Taktik, ständiges Durchnässen und die reinste Form kompetitiven Unsinns — mit privatem Transport inklusive und einem Drink für jeden Kämpfer, wenn der Waffenstillstand ausgerufen wird. Ein Trivlu-Guide organisiert die Session, du entscheidest nur über Teams und Taktik. Das leichtherzigste Kampfformat auf der Prag-Liste: null blaue Flecken, null Könnenshürde und maximale Comedy, besonders sobald die Allianzen zerbrechen. Perfekt für warmes Wetter und Gruppen mit gemischtem Fitnesslevel — es verbrennt Energie, kühlt alle ab und produziert die Art durchnässtes, grinsendes Gruppenfoto, das ein JGA-Wochenende besser zusammenfasst als jedes Nachtclub-Bild."}}', CURRENT_TIMESTAMP),
       ('f062108c-bb53-4a84-9aee-501abc4cc3de', 'wellness-spa', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Wellness & Spa',
        'Every proper stag itinerary needs a recovery slot, and this is it done well. The Wellness & Spa experience comes with a three-hour spa pass covering saunas, pools and relaxation facilities, with showers, dressing rooms and lockers all sorted — plus private roundtrip transport and a Trivlu guide so nobody has to navigate anywhere with a headache. The format is blissfully simple: heat, water, silence, repeat. It is the smartest booking for the day after the big night — the group reassembles slowly, the saunas do their work, and by the final hour everyone is debating dinner plans rather than nursing regrets. Prague''s nightlife takes its toll; this is where you pay it back. Book it in the middle of the weekend and thank yourselves later.',
        87.00, NULL, 120,
        'https://img.trivlu.com/925ee729-280d-4423-a177-9b77a8e6a127.png',
        'Trivlu Guide; Private Transport (Roundtrip); 3 hrs. Spa Pass; Aqua and Sauna entrance; Showers; Dressing rooms and lockers',
        TRUE, '{"de":{"name":"Wellness & Spa","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); 3 Std. Spa-Pass; Eintritt Aqua- und Saunabereich; Duschen; Umkleiden und Schließfächer","description":"Jedes richtige JGA-Programm braucht einen Erholungsslot, und das hier ist er, gut gemacht. Das Wellness-&-Spa-Erlebnis kommt mit einem dreistündigen Spa-Pass für Saunen, Pools und Ruhebereiche, mit Duschen, Umkleiden und Schließfächern, alles geregelt — plus privatem Hin- und Rücktransport und einem Trivlu-Guide, damit niemand mit Kopfschmerzen irgendwohin navigieren muss. Das Format ist herrlich einfach: Hitze, Wasser, Stille, wiederholen. Die cleverste Buchung für den Tag nach der großen Nacht — die Gruppe sammelt sich langsam, die Saunen tun ihre Arbeit, und in der letzten Stunde diskutieren alle über Dinnerpläne statt über Reue. Prags Nachtleben fordert seinen Tribut; hier zahlst du ihn zurück. Buche es in die Mitte des Wochenendes und dank dir später selbst."}}', CURRENT_TIMESTAMP),
       ('36a34f2d-1de0-4d74-8092-08c55637202f', 'whiskey-tasting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Whiskey Tasting',
        'One hour, five whiskies, four countries. This guided tasting seats your group in a cosy Prague bar with a reserved table and walks you through five drams spanning Ireland, Scotland, the USA and Czechia — yes, Czech whisky exists, and finding out how it compares is half the fun. The hour blends tasting with storytelling, pitched for complete beginners and seasoned whiskey drinkers alike, and optional snacks are available to keep things civilised. A Trivlu guide arranges everything. It is the ideal early-evening gear-shift on a stag weekend: the group sits down, the glasses line up, and an hour later everyone leaves with a new favourite and several confidently held opinions. A short, warm, sociable session that upgrades the whole evening that follows it.',
        56.00, NULL, 60,
        'https://img.trivlu.com/886ed0da-6914-42a2-8ee8-d178fa731517.jpg',
        'Trivlu Guide; Table reservation; 5 glasses Whisky for degustation each',
        TRUE, '{"de":{"name":"Whiskey-Verkostung","includes":"Trivlu-Guide; Tischreservierung; 5 Gläser Whisky zur Verkostung pro Person","description":"Eine Stunde, fünf Whiskys, vier Länder. Diese geführte Verkostung setzt deine Gruppe in einer gemütlichen Prager Bar an einen reservierten Tisch und führt dich durch fünf Drams aus Irland, Schottland, den USA und Tschechien — ja, tschechischen Whisky gibt es, und herauszufinden, wie er sich schlägt, ist der halbe Spaß. Die Stunde verbindet Verkostung mit Geschichten, ausgelegt für komplette Anfänger wie für erfahrene Whiskey-Trinker, und optionale Snacks halten das Ganze zivilisiert. Ein Trivlu-Guide organisiert alles. Der ideale Gangwechsel am frühen Abend eines JGA-Wochenendes: Die Gruppe setzt sich, die Gläser reihen sich auf, und eine Stunde später gehen alle mit einem neuen Favoriten und mehreren selbstbewusst vertretenen Meinungen. Eine kurze, warme, gesellige Session, die den ganzen folgenden Abend aufwertet."}}', CURRENT_TIMESTAMP),
       ('026f9337-8b71-45d4-acb2-c0734a2828ae', 'wine-tasting', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'Wine Tasting',
        'For the evening the group decides to be sophisticated — or at least attempt it. This wine tasting is led by a professional French sommelier in an elegant Prague restaurant, working through a curated selection of European and South American wines: white, sparkling, rosé and red, each introduced properly. The experience opens with tapas — cheese and sausages with bread — and includes a two-course meal each, with your table reserved and public transport covered. A Trivlu guide coordinates the evening. Allow three hours: this is a long, relaxed sitting where the sommelier''s stories are as good as the pours. It is the stag weekend''s classiest chapter, ideal for groups who want one genuinely refined night among the chaos — and by the final glass, everyone has strong opinions and precisely none of the vocabulary.',
        95.00, NULL, 180,
        'https://img.trivlu.com/6734a461-db35-42d6-81f3-004374c5a940.avif',
        'Trivlu Guide; Public Transport; Tapas: cheese & sausages with bread; 2-Course Meal each; Wine selection (white; sparkling; rosé; red); Table reservation; Sommelier; Wine presentation',
        TRUE, '{"de":{"name":"Weinverkostung","includes":"Trivlu-Guide; Öffentliche Verkehrsmittel; Tapas: Käse & Wurst mit Brot; 2-Gänge-Menü pro Person; Weinauswahl (weiß, schäumend, rosé, rot); Tischreservierung; Sommelier; Weinpräsentation","description":"Für den Abend, an dem die Gruppe beschließt, kultiviert zu sein — oder es zumindest zu versuchen. Diese Weinverkostung leitet ein professioneller französischer Sommelier in einem eleganten Prager Restaurant und arbeitet sich durch eine kuratierte Auswahl europäischer und südamerikanischer Weine: weiß, schäumend, rosé und rot, jeder ordentlich vorgestellt. Das Erlebnis beginnt mit Tapas — Käse und Wurst mit Brot — und umfasst ein Zwei-Gänge-Menü pro Person, mit reserviertem Tisch und abgedeckten öffentlichen Verkehrsmitteln. Ein Trivlu-Guide koordiniert den Abend. Plane drei Stunden ein: ein langes, entspanntes Sitzen, bei dem die Geschichten des Sommeliers so gut sind wie die Weine. Das eleganteste Kapitel des JGA-Wochenendes, ideal für Gruppen, die inmitten des Chaos einen wirklich kultivierten Abend wollen — und beim letzten Glas haben alle starke Meinungen und exakt null Vokabular."}}', CURRENT_TIMESTAMP),
       ('a10b8a18-4942-438a-81ad-c81426ec307e', 'xxl-cabaret-comedy-show', 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
        'XXL Cabaret Comedy Show',
        'Cabaret with the volume turned up. The XXL Cabaret Comedy Show is a lively adult stage performance in Prague that mixes comedy, dance and theatrical numbers into one hour of gloriously unserious entertainment — and backs it with a full hour of unlimited beer plus a 15-minute show performance for your group. A Trivlu guide books it all in. The format is built for stag groups: it needs no concentration, it rewards heckling-adjacent enthusiasm, and it gets funnier with every round the unlimited beer provides. Book it as the bridge between dinner and the clubs — the group arrives as an audience, leaves as a choir, and the night''s momentum problem is solved for good. One hour, big laughs, bigger performers.',
        39.00, 130.00, 60,
        'https://img.trivlu.com/2cf99c79-d108-47d6-8153-fad53db5fb5a.webp',
        'Trivlu Guide; 15 min. Strip Show; Hour of unlimited beer',
        TRUE, '{"de":{"name":"XXL-Cabaret-Comedy-Show","includes":"Trivlu-Guide; 15 Min. Stripshow; Eine Stunde unbegrenzt Bier","description":"Cabaret mit aufgedrehter Lautstärke. Die XXL-Cabaret-Comedy-Show ist eine lebhafte Erwachsenen-Bühnenshow in Prag, die Comedy, Tanz und Theaternummern zu einer Stunde herrlich unernster Unterhaltung mischt — und das Ganze mit einer vollen Stunde unbegrenzt Bier plus einer 15-minütigen Show für deine Gruppe unterfüttert. Ein Trivlu-Guide bucht alles. Das Format ist für JGA-Gruppen gemacht: Es braucht keine Konzentration, belohnt Begeisterung hart an der Grenze zum Zwischenruf und wird mit jeder Runde des unbegrenzten Biers lustiger. Buche es als Brücke zwischen Dinner und Clubs — die Gruppe kommt als Publikum, geht als Chor, und das Schwungproblem der Nacht ist endgültig gelöst. Eine Stunde, große Lacher, größere Performer."}}', CURRENT_TIMESTAMP);

